/* DAWAH X — ahmad, অধ্যায় 124 · খণ্ড 124 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][124]=[[24601,24601,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدَةَ بْنِ أَبِي لُبَابَةَ ‏ ‏عَنْ ‏ ‏هِلَالٍ يَعْنِي ابْنَ يَسَافٍ ‏ ‏عَنْ ‏ ‏فَرْوَةَ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ ‏","","",""],[24602,24602,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هَارُونَ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ ‏ { ‏فَرَوْحٌ ‏ ‏وَرَيْحَانٌ ‏}","","",""],[24603,24603,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏أَتَتْهَا وَهِيَ ‏ ‏مُكَاتَبَةٌ ‏ ‏قَدْ كَاتَبَهَا أَهْلُهَا عَلَى تِسْعِ ‏ ‏أَوَاقٍ ‏ ‏فَقَالَتْ لَهَا إِنْ شَاءَ أَهْلُكِ عَدَدْتُهَا لَهُمْ ‏ ‏عَدَّةً ‏ ‏وَاحِدَةً وَكَانَ ‏ ‏الْوَلَاءُ ‏ ‏لِي فَأَتَتْ أَهْلَهَا فَذَكَرَتْ ذَلِكَ لَهُمْ ‏ ‏وَأَبَوْا ‏ ‏إِلَّا أَنْ يَشْتَرِطُوا الْوَلَاءَ لَهُمْ فَذَكَرَتْهُ ‏ ‏عَائِشَةُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ افْعَلِي فَفَعَلَتْ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَ النَّاسَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ قَالَ مَا بَالُ رِجَالٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللَّهِ قَالَ ‏ ‏كُلُّ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ فَهُوَ بَاطِلٌ كِتَابُ اللَّهِ أَحَقُّ وَشَرْطُهُ ‏ ‏أَوْثَقُ ‏ ‏وَالْوَلَاءُ لِمَنْ أَعْتَقَ ‏","","",""],[24604,24604,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَنْ حَدَّثَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ قَائِمًا بَعْدَمَا أُنْزِلَ عَلَيْهِ ‏ ‏الْفُرْقَانُ ‏ ‏فَلَا تُصَدِّقْهُ ‏ ‏مَا بَالَ قَائِمًا مُنْذُ أُنْزِلَ عَلَيْهِ ‏ ‏الْفُرْقَانُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِي حَدِيثِهِ مَا بَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا مُنْذُ أُنْزِلَ عَلَيْهِ الْفُرْقَانُ ‏","","",""],[24605,24605,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏سَوْدَةَ ‏ ‏كَانَتْ امْرَأَةً ‏ ‏ثَبْطَةً ‏ ‏ثَقِيلَةً ‏ ‏اسْتَأْذَنَتْ النَّبِيَّ أَنْ ‏ ‏تَدْفَعَ ‏ ‏قَبْلَ ‏ ‏دَفْعِهِ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏فَأَذِنَ لَهَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَدِدْتُ أَنِّي كُنْتُ اسْتَأْذَنْتُهُ ‏","","",""],[24606,24606,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَفَرٍ وَقَدْ سُتِرْتُ بِنَمَطٍ فِيهِ تَمَاثِيلُ قَالَتْ فَنَحَّاهُ قَالَتْ وَاتَّخَذْتُ مِنْهُ وِسَادَتَيْنِ ‏","","",""],[24607,24607,"","","‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ بِيَدَيَّ هَاتَيْنِ عِنْدَ إِحْرَامِهِ وَحِينَ رَمَى قَبْلَ أَنْ يَزُورَ ‏","","",""],[24608,24608,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَعِنْدَهَا رَجُلٌ قَالَ فَقَالَ مَنْ هَذَا قَالَتْ أَخِي مِنْ الرَّضَاعَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرُوا مَنْ تُرْضِعُونَ فَإِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏انْظُرْنَ مَا إِخْوَانُكُنَّ إِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏","","",""],[24609,24609,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَخْبِرِينِي عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقُلْتُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ أَوَّلَهُ وَيَقُومُ آخِرَهُ فَإِذَا قَامَ تَوَضَّأَ وَصَلَّى مَا قَضَى اللَّهُ عَزَّ وَجَلَّ لَهُ فَإِنْ كَانَ بِهِ حَاجَةٌ إِلَى أَهْلِهِ ‏ ‏أَتَى ‏ ‏أَهْلَهُ وَإِلَّا مَالَ إِلَى فِرَاشِهِ فَإِنْ كَانَ ‏ ‏أَتَى ‏ ‏أَهْلَهُ نَامَ كَهَيْئَتِهِ لَمْ يَمَسَّ مَاءً حَتَّى إِذَا كَانَ عِنْدَ أَوَّلِ الْأَذَانِ ‏ ‏وَثَبَ ‏ ‏وَاللَّهِ مَا قَالَتْ قَامَ وَإِنْ كَانَ جُنُبًا أَفَاضَ عَلَيْهِ الْمَاءَ وَاللَّهِ مَا قَالَتْ اغْتَسَلَ وَلَا تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ ‏","","",""],[24610,24610,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَكُونُ حَائِضًا فَآخُذُ ‏ ‏الْعَرْقَ ‏ ‏فَأَتَعَرَّقُهُ وَأَنَا حَائِضٌ فَأُنَاوِلُهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ وَأَشْرَبُ وَأَنَا حَائِضٌ فَأُنَاوِلُهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ فَاهُ عَلَى مَوْضِعِ ‏ ‏فِيَّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كُنْتُ ‏ ‏أَتَعَرَّقُ ‏ ‏الْعَظْمَ وَأَنَا حَائِضٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[24611,24611,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ غَالِبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا رَجُلٍ قَتَلَ فَقُتِلَ أَوْ رَجُلٍ زَنَى بَعْدَمَا ‏ ‏أُحْصِنَ ‏ ‏أَوْ رَجُلٍ ارْتَدَّ بَعْدَ إِسْلَامِهِ ‏","","",""],[24612,24612,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا ‏ ‏قُبِضَ ‏ ‏كُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ يَمَانِيَةٍ بِيضٍ ‏ ‏كُرْسُفٍ ‏ ‏لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ ‏","","",""],[24613,24613,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏وَالْعَبَّاسِ بْنِ ذُرَيْحٍ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏قَالَ ‏ ‏الْعَبَّاسُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَقَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏فَقَالَتْ إِنِّي حَائِضٌ قَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ ‏","","",""],[24614,24614,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ ‏ ‏وَدِدْتُ أَنَّ عِنْدِي بَعْضَ أَصْحَابِي قُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَسَكَتَ قُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏عُمَرَ ‏ ‏فَسَكَتَ قُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏عَلِيًّا ‏ ‏فَسَكَتَ قُلْنَا أَلَا ‏ ‏نَدْعُو لَكَ ‏ ‏عُثْمَانَ ‏ ‏قَالَ بَلَى قَالَ أَرْسَلْنَا إِلَى ‏ ‏عُثْمَانَ ‏ ‏فَجَاءَ ‏ ‏فَخَلَا بِهِ فَجَعَلَ يُكَلِّمُهُ وَوَجْهُ ‏ ‏عُثْمَانَ ‏ ‏يَتَغَيَّرُ ‏","","",""],[24615,24615,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُرِقَتْ ‏ ‏مِخْنَقَتِي ‏ ‏فَدَعَوْتُ عَلَى صَاحِبِهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُسَبِّخِي ‏ ‏عَلَيْهِ دَعِيهِ بِذَنْبِهِ ‏","","",""],[24616,24616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَّرَ الطَّوَافَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏إِلَى اللَّيْلِ ‏","","",""],[24617,24617,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[24618,24618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ شَبِعْنَا مِنْ ‏ ‏الْأَسْوَدَيْنِ ‏ ‏الْمَاءِ وَالتَّمْرِ ‏","","",""],[24619,24619,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَالْمُنْذِرِ بْنِ أَبِي الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَظَرَ إِلَى الْقَمَرِ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏اسْتَعِيذِي بِاللَّهِ مِنْ شَرِّ هَذَا فَإِنَّ هَذَا ‏ ‏الْغَاسِقُ ‏ ‏إِذَا ‏ ‏وَقَبَ ‏","","",""],[24620,24620,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ بَكْرٍ ‏ ‏أَنَّهَا ‏ ‏أَخْبَرَتْهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏الْمَرْأَةِ ‏ ‏تَرَى مَا يُرِيبُهَا بَعْدَ الطُّهْرِ قَالَ إِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏أَوْ قَالَ عُرُوقٌ ‏","","",""],[24621,24621,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شَيْبَةَ ‏ ‏خَازِنَ ‏ ‏الْبَيْتِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَرَقَهُ ‏ ‏وَجَعٌ فَجَعَلَ ‏ ‏يَشْتَكِي ‏ ‏وَيَتَقَلَّبُ عَلَى فِرَاشِهِ فَقَالَتْ لَهُ ‏ ‏عَائِشَةُ ‏ ‏لَوْ فَعَلَ هَذَا بَعْضُنَا ‏ ‏لَوَجِدْتَ عَلَيْهِ فَقَالَ ‏ ‏إِنَّ الْمُؤْمِنِينَ يُشَدَّدُ عَلَيْهِمْ فَإِنَّهُ لَيْسَ مِنْ مُؤْمِنٍ يُصِيبُهُ ‏ ‏نَكْبَةٌ ‏ ‏شَوْكَةٌ وَلَا وَجَعٌ إِلَّا رَفَعَ اللَّهَ عَزَّ وَجَلَّ لَهُ بِهَا دَرَجَةً وَحَطَّ بِهَا عَنْهُ خَطِيئَةً ‏ ‏أَوْ كَالَّذِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24622,24622,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏يُصَلِّي مَا بَيْنَ أَنْ ‏ ‏يَفْرُغَ ‏ ‏مِنْ صَلَاةِ الْعِشَاءِ وَهِيَ الَّتِي تُسَمُّونَ ‏ ‏أَوْ تَدْعُونَ ‏ ‏الْعَتَمَةَ ‏ ‏إِلَى الْفَجْرِ إِحْدَى عَشْرَةَ سَجْدَةً يُسَلِّمُ بَيْنَ كُلِّ سَجْدَتَيْنِ ‏ ‏وَيُوتِرُ ‏ ‏بِوَاحِدَةٍ وَيَسْجُدُ فِي ‏ ‏سُبْحَتِهِ ‏ ‏بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ فَإِذَا سَكَتَ الْمُؤَذِّنُ بِالْأُولَى مِنْ صَلَاةِ الصُّبْحِ رَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى ‏ ‏شِقِّهِ ‏ ‏الْأَيْمَنِ فَيَأْتِيهِ الْمُؤَذِّنُ فَيَخْرُجُ مَعَهُ ‏","","",""],[24623,24623,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَرَ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبِّحُ ‏ ‏سُبْحَةَ الضُّحَى وَإِنِّي ‏ ‏لَأُسَبِّحُهَا ‏","","",""],[24624,24624,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَمَ ‏ ‏بِصَلَاةِ الْعِشَاءِ ذَاتَ لَيْلَةٍ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا مِنْ النَّاسِ مِنْ أَحَدٍ يَنْتَظِرُ هَذِهِ الصَّلَاةَ غَيْرَكُمْ ‏ ‏قَالَ ‏ ‏وَذَاكَ قَبْلَ أَنْ ‏ ‏يَفْشُوَ ‏ ‏الْإِسْلَامُ فِي النَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَمَ ‏ ‏لَيْلَةً ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[24625,24625,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ أَحَدًا أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24626,24626,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ ‏ ‏عَنْ ‏ ‏دِقْرَةَ ‏ ‏أُمِّ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أُذَيْنَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَطُوفُ مَعَ ‏ ‏عَائِشَةَ ‏ ‏بِالْبَيْتِ ‏ ‏فَأَتَاهَا بَعْضُ أَهْلِهَا فَقَالَ إِنَّكِ قَدْ عَرَقْتِ فَغَيِّرِي ثِيَابَكِ فَوَضَعَتْ ثَوْبًا كَانَ عَلَيْهَا فَعَرَضْتُ عَلَيْهِ ‏ ‏بُرْدًا ‏ ‏عَلَيَّ مُصَلَّبًا فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَآهُ فِي ثَوْبٍ ‏ ‏قَضَبَهُ ‏ ‏قَالَتْ ‏ ‏فَلَمْ تَلْبَسْهُ ‏","","",""],[24627,24627,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَعْلَمُ النَّاسِ بِهَذَا الْحَدِيثِ قَالَ ‏ ‏بَلَغَ ‏ ‏مَرْوَانُ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏مَنْ أَدْرَكَهُ الصُّبْحُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏فَلَا يَصُومَنَّ يَوْمَئِذٍ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏يَسْأَلُهَا عَنْ ذَاكَ فَانْطَلَقَتْ مَعَهُ فَسَأَلَهَا فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ ‏ ‏فَرَجَعَ إِلَى ‏ ‏مَرْوَانَ ‏ ‏فَحَدَّثَهُ فَقَالَ الْقَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَحَدِّثْهُ فَقَالَ إِنَّهُ لَجَارِي وَإِنِّي لَأَكْرَهُ أَنْ أَسْتَقْبِلَهُ بِمَا يَكْرَهُ فَقَالَ ‏ ‏أَعْزِمُ ‏ ‏عَلَيْكَ لَتَلْقَيَنَّهُ قَالَ فَلَقِيَهُ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَاللَّهِ إِنْ كُنْتُ لَأَكْرَهُ أَنْ أَسْتَقْبِلَكَ بِمَا تَكْرَهُ وَلَكِنَّ الْأَمِيرَ ‏ ‏عَزَمَ ‏ ‏عَلَيَّ قَالَ فَحَدَّثْتُهُ فَقَالَ ‏ ‏حَدَّثَنِيهِ ‏ ‏الْفَضْلُ ‏","","",""],[24628,24628,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ الْمَصَّةُ وَلَا الْمَصَّتَانِ ‏","","",""],[24629,24629,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏سُئِلَتْ ‏ ‏عَائِشَةُ ‏ ‏عَنْ خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَ ‏ ‏خُلُقُهُ الْقُرْآنَ ‏","","",""],[24630,24630,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَيْ ‏ ‏أُمَّهْ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏قَالَتْ نَعَمْ لَمْ يَكُنْ يَنَامُ حَتَّى يَغْسِلَ فَرْجَهُ وَيَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[24631,24631,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَمَسْرُوقٍ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عَائِشَةَ ‏ ‏لِنَسْأَلَهَا عَنْ ‏ ‏الْمُبَاشَرَةِ ‏ ‏لِلصَّائِمِ فَاسْتَحَيْنَا فَقُمْنَا قَبْلَ أَنْ نَسْأَلَهَا فَمَشَيْنَا لَا أَدْرِي كَمْ ثُمَّ قُلْنَا جِئْنَا لِنَسْأَلَهَا عَنْ حَاجَةٍ ثُمَّ نَرْجِعُ قَبْلَ أَنْ نَسْأَلَهَا فَرَجَعْنَا فَقُلْنَا يَا أُمَّ الْمُؤْمِنِينَ إِنَّا جِئْنَا لِنَسْأَلَكِ عَنْ شَيْءٍ فَاسْتَحَيْنَا فَقُمْنَا فَقَالَتْ مَا هُوَ سَلَا عَمَّا بَدَا لَكُمَا قُلْنَا أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ قَالَتْ قَدْ كَانَ يَفْعَلُ ذَلِكَ وَلَكِنَّهُ كَانَ أَمْلَكَ ‏ ‏لِإِرْبِهِ ‏ ‏مِنْكُمْ ‏","","",""],[24632,24632,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كَانَ يَقْضِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُسْلَهُ مِنْ الْجَنَابَةِ قَالَ فَدَعَتْ بِإِنَاءٍ ‏ ‏حَزَرَتْهُ ‏ ‏صَاعًا ‏ ‏بِصَاعِكُمْ هَذَا ‏","","",""],[24633,24633,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يَقُولُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحِلِّهِ ‏ ‏وَلِحُرْمِهِ ‏","","",""],[24634,24634,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُ ‏ ‏بِالْهَدْيِ ‏ ‏فَأَفْتِلُ ‏ ‏قَلَائِدَهَا ‏ ‏بِيَدَيَّ ثُمَّ لَا يُمْسِكُ عَنْ شَيْءٍ لَا يُمْسِكُ عَنْهُ الْحَلَالُ ‏","","",""],[24635,24635,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يُصَلِّي أَرْبَعًا قَبْلَ الظُّهْرِ وَثِنْتَيْنِ بَعْدَهَا وَثِنْتَيْنِ قَبْلَ الْعَصْرِ ‏ ‏وَثِنْتَيْنِ بَعْدَ الْمَغْرِبِ وَثِنْتَيْنِ بَعْدَ الْعِشَاءِ ثُمَّ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ تِسْعًا قُلْتُ أَقَائِمًا أَوْ قَاعِدًا قَالَتْ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا قَاعِدًا قُلْتُ كَيْفَ يَصْنَعُ إِذَا كَانَ قَائِمًا وَكَيْفَ يَصْنَعُ إِذَا كَانَ قَاعِدًا قَالَتْ إِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا وَرَكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ ‏","","",""],[24636,24636,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لِابْنِ أَبِي السَّائِبِ ‏ ‏قَاصِّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ثَلَاثًا لَتُبَايِعَنِّي عَلَيْهِنَّ أَوْ ‏ ‏لَأُنَاجِزَنَّكَ ‏ ‏فَقَالَ مَا هُنَّ بَلْ أَنَا أُبَايِعُكِ يَا أُمَّ الْمُؤْمِنِينَ قَالَتْ ‏ ‏اجْتَنِبْ ‏ ‏السَّجْعَ ‏ ‏مِنْ الدُّعَاءِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ كَانُوا لَا يَفْعَلُونَ ذَلِكَ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً فَقَالَتْ إِنِّي عَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ وَهُمْ لَا يَفْعَلُونَ ذَاكَ ‏ ‏وَقُصَّ عَلَى النَّاسِ فِي كُلِّ جُمُعَةٍ مَرَّةً فَإِنْ أَبَيْتَ فَثِنْتَيْنِ فَإِنْ أَبَيْتَ فَثَلَاثًا فَلَا تَمَلُّ النَّاسُ هَذَا الْكِتَابَ وَلَا أَلْقَيَنَّكَ تَأْتِي الْقَوْمَ وَهُمْ فِي حَدِيثٍ مِنْ حَدِيثِهِمْ فَتَقْطَعُ عَلَيْهِمْ حَدِيثَهُمْ وَلَكِنْ اتْرُكْهُمْ فَإِذَا ‏ ‏جَرَّءُوكَ ‏ ‏عَلَيْهِ وَأَمَرُوكَ بِهِ فَحَدِّثْهُمْ ‏","","",""],[24637,24637,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي سُجُودِ الْقُرْآنِ بِاللَّيْلِ يَقُولُهُ فِي السَّجْدَةِ مِرَارًا ‏ ‏سَجَدَ ‏ ‏وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ ‏ ‏بِحَوْلِهِ ‏ ‏وَقُوَّتِهِ ‏","","",""],[24638,24638,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُرْدُ بْنُ سِنَانٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي الثَّوْبِ الَّذِي يُجَامِعُ فِيهِ ‏","","",""],[24639,24639,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏امْرَأَةُ أَبِي أَرْضَعَتْ جَارِيَةً مِنْ ‏ ‏عُرْضِ النَّاسِ ‏ ‏بِلَبَنِ أَخَوَيَّ ‏ ‏أَفَتَرَى أَنِّي أَتَزَوَّجُهَا فَقَالَ لَا أَبُوكَ أَبُوهَا قَالَ ثُمَّ حَدَّثَ حَدِيثَ ‏ ‏أَبِي الْقُعَيْسِ ‏ ‏فَقَالَ ‏ ‏إِنَّ ‏ ‏أَبَا الْقُعَيْسِ ‏ ‏أَتَى ‏ ‏عَائِشَةَ ‏ ‏يَسْتَأْذِنُ عَلَيْهَا فَلَمْ تَأْذَنْ لَهُ فَلَمَّا جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا قُعَيْسٍ ‏ ‏جَاءَ يَسْتَأْذِنُ عَلَيَّ فَلَمْ آذَنْ لَهُ فَقَالَ ‏ ‏هُوَ عَمُّكِ فَلْيَدْخُلْ عَلَيْكِ فَقُلْتُ إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ فَقَالَ هُوَ عَمُّكَ فَلْيَدْخُلْ عَلَيْكِ ‏","","",""],[24640,24640,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ ‏ ‏قِيَامُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ قَدْرَ مَا يَقْرَأُ ‏ ‏فَاتِحَةَ الْكِتَابَ ‏","","",""],[24641,24641,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ الْمغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏بَعَثَ إِلَيْنَا آلُ ‏ ‏أَبِي بَكْرٍ ‏ ‏بِقَائِمَةِ شَاةٍ لَيْلًا فَأَمْسَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَطَعْتُ ‏ ‏أَوْ أَمْسَكْتُ وَقَطَعَ ‏ ‏فَقَالَ الَّذِي تُحَدِّثُهُ أَعَلَى غَيْرِ مِصْبَاحٍ فَقَالَتْ لَوْ كَانَ عِنْدَنَا مِصْبَاحٌ ‏ ‏لَائْتَدَمْنَا ‏ ‏بِهِ إِنْ ‏ ‏كَانَ لَيَأْتِي عَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ مَا يَخْتَبِزُونَ خُبْزًا وَلَا يَطْبُخُونَ قِدْرًا ‏","","",""],[24642,24642,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ وَهُوَ قَاعِدٌ فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ قَدْرَ مَا يَقْرَأُ إِنْسَانٌ أَرْبَعِينَ آيَةً ‏","","",""],[24643,24643,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ امْرَأَةً دَخَلَتْ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَإِذَا رُمْحٌ مَنْصُوبٌ فَقَالَتْ مَا هَذَا الرُّمْحُ فَقَالَتْ نَقْتُلُ بِهِ ‏ ‏الْأَوْزَاغَ ‏ ‏ثُمَّ حَدَّثَتْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏لَمَّا أُلْقِيَ فِي النَّارِ جَعَلَتْ الدَّوَابُّ كُلُّهَا تُطْفِئُ عَنْهُ إِلَّا ‏ ‏الْوَزَغَ ‏ ‏فَإِنَّهُ جَعَلَ يَنْفُخُهَا عَلَيْهِ ‏","","",""],[24644,24644,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِذَا بُدِّلَتْ ‏ { ‏الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ ‏} ‏أَيْنَ النَّاسُ يَوْمَئِذٍ قَالَ ‏ ‏النَّاسُ يَوْمَئِذٍ عَلَى الصِّرَاطِ ‏","","",""],[24645,24645,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَيَزِيدُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا أَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ السُّوَرَ قَالَتْ ‏ ‏الْمُفَصَّلَ ‏ ‏قُلْتُ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَاعِدًا قَالَتْ نَعَمْ بَعْدَمَا حَطَمَهُ النَّاسُ قُلْتُ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَتْ لَا إِلَّا أَنْ يَجِيءَ مِنْ ‏ ‏مَغِيبِهِ ‏ ‏قُلْتُ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ شَهْرًا سِوَى رَمَضَانَ قَالَتْ لَا وَاللَّهِ إِنْ صَامَ شَهْرًا تَامًّا سِوَى رَمَضَانَ وَلَا أَفْطَرَهُ كُلَّهُ حَتَّى يَصُومَ مِنْهُ شَيْئًا قُلْتُ أَيُّ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَحَبَّ إِلَيْهِ قَالَتْ ‏ ‏أَبُو بَكْرٍ ‏ ‏قُلْتُ ثُمَّ مَنْ قَالَتْ ثُمَّ ‏ ‏عُمَرُ ‏ ‏قُلْتُ ثُمَّ مَنْ قَالَتْ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏قُلْتُ ثُمَّ مَنْ قَالَ فَسَكَتَتْ ‏","","",""],[24646,24646,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ ‏ ‏ذَكَرُوا عِنْدَ ‏ ‏أَبِي قِلَابَةَ ‏ ‏خُرُوجَ النِّسَاءِ فِي الْعِيدِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَتْ ‏ ‏الْكِعَابُ ‏ ‏تَخْرُجُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏خِدْرِهَا ‏","","",""],[24647,24647,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ عَزَّ وَجَلَّ كَرِهَ اللَّهُ لِقَاءَهُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ كَرَاهِيَةُ لِقَاءِ اللَّهِ أَنْ يَكْرَهَ الْمَوْتَ فَوَاللَّهِ إِنَّا لَنَكْرَهُهُ فَقَالَ لَا لَيْسَ بِذَاكَ وَلَكِنَّ الْمُؤْمِنَ إِذَا قَضَى اللَّهُ عَزَّ وَجَلَّ قَبْضَهُ فَرَّجَ لَهُ عَمَّا بَيْنَ يَدَيْهِ مِنْ ثَوَابِ اللَّهِ عَزَّ وَجَلَّ وَكَرَامَتِهِ فَيَمُوتُ حِينَ يَمُوتُ وَهُوَ يُحِبُّ لِقَاءَ اللَّهِ عَزَّ وَجَلَّ وَاللَّهُ يُحِبُّ لِقَاءَهُ وَإِنَّ الْكَافِرَ وَالْمُنَافِقَ إِذَا قَضَى اللَّهُ عَزَّ وَجَلَّ قَبْضَهُ فَرَّجَ لَهُ عَمَّا بَيْنَ يَدَيْهِ مِنْ عَذَابِ اللَّهِ عَزَّ وَجَلَّ وَهَوَانِهِ فَيَمُوتُ حِينَ يَمُوتُ وَهُوَ يَكْرَهُ لِقَاءَ اللَّهِ وَاللَّهُ يَكْرَهُ لِقَاءَهُ ‏","","",""],[24648,24648,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا يَدَعُ حَاجَةً لَهُ إِلَى امْرَأَتِهِ حَتَّى يَرْجِعَ الْحَاجُّ ‏","","",""],[24649,24649,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَيُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُقْبَلُ صَلَاةُ حَائِضٍ إِلَّا ‏ ‏بِخِمَارٍ ‏","","",""],[24650,24650,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقْبَلُ اللَّهُ صَلَاةَ حَائِضٍ إِلَّا ‏ ‏بِخِمَارٍ ‏","","",""],[24651,24651,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمَيَّةَ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ هَذِهِ الْآيَةِ ‏ { ‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏} ‏وَعَنْ هَذِهِ الْآيَةِ ‏ { ‏مَنْ يَعْمَلْ سُوءًا ‏ ‏يُجْزَ ‏ ‏بِهِ ‏} ‏فَقَالَتْ مَا سَأَلَنِي عَنْهُمَا أَحَدٌ مُنْذُ سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُمَا فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏هَذِهِ مُتَابَعَةُ اللَّهِ عَزَّ وَجَلَّ الْعَبْدَ بِمَا يُصِيبُهُ مِنْ ‏ ‏الْحُمَّةِ ‏ ‏وَالنَّكْبَةِ وَالشَّوْكَةِ حَتَّى الْبِضَاعَةُ يَضَعُهَا فِي كُمِّهِ فَيَفْقِدُهَا فَيَفْزَعُ لَهَا فَيَجِدُهَا فِي ‏ ‏ضِبْنِهِ ‏ ‏حَتَّى إِنَّ الْمُؤْمِنَ لَيَخْرُجُ مِنْ ذُنُوبِهِ كَمَا يَخْرُجُ ‏ ‏التِّبْرُ ‏ ‏الْأَحْمَرُ مِنْ ‏ ‏الْكِيرِ ‏","","",""],[24652,24652,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏","","",""],[24653,24653,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي الصَّلْتِ ‏ ‏قَالَ ‏ ‏ذَكَرُوا عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏رَحِمَهُ اللَّهُ اسْتِقْبَالَ الْقِبْلَةِ بِالْفُرُوجِ ‏ ‏فَقَالَ ‏ ‏عِرَاكُ بْنُ مَالِكٍ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏ذَكَرُوا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ قَوْمًا يَكْرَهُونَ ذَلِكَ قَالَ فَقَالَ قَدْ فَعَلُوهَا ‏ ‏حَوِّلُوا مَقْعَدَتِي نَحْوَ الْقِبْلَةِ ‏","","",""],[24654,24654,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَبَّيْنَا بِالْحَجِّ حَتَّى إِذَا كُنَّا ‏ ‏بِسَرِفٍ ‏ ‏حِضْتُ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَبْكِي فَقَالَ مَا ‏ ‏يُبْكِيكِ يَا ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ حِضْتُ لَيْتَنِي لَمْ أَكُنْ حَجَجْتُ قَالَ سُبْحَانَ اللَّهِ ‏ ‏إِنَّمَا ذَاكَ شَيْءٌ كَتَبَهُ اللَّهُ عَزَّ وَجَلَّ عَلَى بَنَاتِ ‏ ‏آدَمَ ‏ ‏انْسُكِي ‏ ‏الْمَنَاسِكَ ‏ ‏كُلَّهَا غَيْرَ أَنْ لَا ‏ ‏تَطُوفِي ‏ ‏بِالْبَيْتِ ‏ ‏قَالَتْ فَلَمَّا دَخَلْنَا ‏ ‏مَكَّةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَاءَ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَجْعَلْهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏قَالَتْ وَذَبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نِسَائِهِ الْبَقَرَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏فَلَمَّا كَانَتْ لَيْلَةَ ‏ ‏الْبَطْحَاءِ ‏ ‏طَهُرَتْ فَقَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَرْجِعُ صَوَاحِبِي بِحَجَّةٍ وَعُمْرَةٍ وَأَرْجِعُ أَنَا بِحَجَّةٍ فَأَمَرَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ ‏ ‏فَذَهَبَ بِي إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَلَبَّيْتُ بِعُمْرَةٍ ‏","","",""],[24655,24655,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ ‏ ‏يُضَاهُونَ ‏ ‏بِخَلْقِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[24656,24656,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏جَعَلَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُرْدَةً ‏ ‏مِنْ صُوفٍ سَوْدَاءَ فَلَبِسَهَا فَلَمَّا عَرِقَ فَوَجَدَ رِيحَ الصُّوفِ فَقَذَفَهَا ‏ ‏قَالَ وَأَحْسِبُهُ قَالَ وَكَانَ يُعْجِبُهُ الرِّيحُ الطَّيِّبَةُ ‏","","",""],[24657,24657,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ أَنَا وَصَاحِبٌ لِي إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَاسْتَأْذَنَّا عَلَيْهَا فَأَلْقَتْ لَنَا وَسَادَةً وَجَذَبَتْ إِلَيْهَا الْحِجَابَ فَقَالَ صَاحِبِي يَا أُمَّ الْمُؤْمِنِينَ مَا تَقُولِينَ فِي ‏ ‏الْعِرَاكِ ‏ ‏قَالَتْ وَمَا ‏ ‏الْعِرَاكُ ‏ ‏وَضَرَبْتُ ‏ ‏مَنْكِبَ ‏ ‏صَاحِبِي فَقَالَتْ ‏ ‏مَهْ ‏ ‏آذَيْتَ أَخَاكَ ثُمَّ قَالَتْ مَا ‏ ‏الْعِرَاكُ ‏ ‏الْمَحِيضُ قُولُوا مَا قَالَ اللَّهُ الْمَحِيضُ ثُمَّ قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَشَّحُنِي وَيَنَالُ مِنْ رَأْسِي وَبَيْنِي وَبَيْنَهُ ثَوْبٌ وَأَنَا حَائِضٌ ‏","","",""],[24658,24658,"","","‏ ‏ثُمَّ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرَّ بِبَابِي مِمَّا يُلْقِي الْكَلِمَةَ يَنْفَعُ اللَّهُ عَزَّ وَجَلَّ بِهَا فَمَرَّ ذَاتَ يَوْمٍ فَلَمْ يَقُلْ شَيْئًا ثُمَّ مَرَّ أَيْضًا فَلَمْ يَقُلْ شَيْئًا مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قُلْتُ يَا جَارِيَةُ ضَعِي لِي وِسَادَةً عَلَى الْبَابِ وَعَصَبْتُ رَأْسِي فَمَرَّ بِي فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏مَا شَأْنُكِ فَقُلْتُ ‏ ‏أَشْتَكِي ‏ ‏رَأْسِي فَقَالَ ‏ ‏أَنَا وَا ‏ ‏رَأْسَاهْ فَذَهَبَ فَلَمْ يَلْبَثْ إِلَّا يَسِيرًا حَتَّى جِيءَ بِهِ مَحْمُولًا فِي كِسَاءٍ فَدَخَلَ عَلَيَّ وَبَعَثَ إِلَى النِّسَاءِ فَقَالَ إِنِّي قَدْ ‏ ‏اشْتَكَيْتُ ‏ ‏وَإِنِّي لَا أَسْتَطِيعُ أَنْ أَدُورَ بَيْنَكُنَّ فَأْذَنَّ لِي فَلْأَكُنْ عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏صَفِيَّةَ ‏ ‏وَلَمْ أُمَرِّضْ أَحَدًا قَبْلَهُ فَبَيْنَمَا رَأْسُهُ ذَاتَ يَوْمٍ عَلَى ‏ ‏مَنْكِبَيَّ ‏ ‏إِذْ مَالَ رَأْسُهُ نَحْوَ رَأْسِي فَظَنَنْتُ أَنَّهُ يُرِيدُ مِنْ رَأْسِي حَاجَةً فَخَرَجَتْ مِنْ ‏ ‏فِيهِ ‏ ‏نُطْفَةٌ ‏ ‏بَارِدَةٌ فَوَقَعَتْ عَلَى ‏ ‏ثُغْرَةِ ‏ ‏نَحْرِي فَاقْشَعَرَّ لَهَا جِلْدِي فَظَنَنْتُ أَنَّهُ ‏ ‏غُشِيَ ‏ ‏عَلَيْهِ ‏ ‏فَسَجَّيْتُهُ ‏ ‏ثَوْبًا فَجَاءَ ‏ ‏عُمَرُ ‏ ‏وَالْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَاسْتَأْذَنَا فَأَذِنْتُ لَهُمَا وَجَذَبْتُ إِلَيَّ الْحِجَابَ فَنَظَرَ ‏ ‏عُمَرُ ‏ ‏إِلَيْهِ فَقَالَ ‏ ‏وَا ‏ ‏غَشْيَاهْ ‏ ‏مَا أَشَدُّ ‏ ‏غَشْيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَامَا فَلَمَّا دَنَوَا مِنْ الْبَابِ قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏يَا ‏ ‏عُمَرُ ‏ ‏مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَذَبْتَ بَلْ أَنْتَ رَجُلٌ تَحُوسُكَ ‏ ‏فِتْنَةٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمُوتُ حَتَّى يُفْنِيَ اللَّهُ عَزَّ وَجَلَّ الْمُنَافِقِينَ ثُمَّ جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَرَفَعْتُ الْحِجَابَ فَنَظَرَ إِلَيْهِ فَقَالَ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَتَاهُ مِنْ قِبَلِ رَأْسِهِ ‏ ‏فَحَدَرَ ‏ ‏فَاهُ وَقَبَّلَ جَبْهَتَهُ ثُمَّ قَالَ وَا ‏ ‏نَبِيَّاهْ ثُمَّ رَفَعَ رَأْسَهُ ثُمَّ ‏ ‏حَدَرَ ‏ ‏فَاهُ وَقَبَّلَ جَبْهَتَهُ ثُمَّ قَالَ وَا ‏ ‏صَفِيَّاهْ ثُمَّ رَفَعَ رَأْسَهُ وَحَدَرَ فَاهُ وَقَبَّلَ جَبْهَتَهُ وَقَالَ وَا ‏ ‏خَلِيلَاهْ مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ إِلَى الْمَسْجِدِ ‏ ‏وَعُمَرُ ‏ ‏يَخْطُبُ النَّاسَ وَيَتَكَلَّمُ وَيَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمُوتُ حَتَّى يُفْنِيَ اللَّهُ عَزَّ وَجَلَّ الْمُنَافِقِينَ فَتَكَلَّمَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ ‏} ‏حَتَّى فَرَغَ مِنْ الْآيَةِ ‏ { ‏وَمَا ‏ ‏مُحَمَّدٌ ‏ ‏إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَى أَعْقَابِكُمْ ‏} ‏حَتَّى فَرَغَ مِنْ الْآيَةِ فَمَنْ كَانَ يَعْبُدُ اللَّهَ عَزَّ وَجَلَّ فَإِنَّ اللَّهَ حَيٌّ وَمَنْ كَانَ يَعْبُدُ ‏ ‏مُحَمَّدًا ‏ ‏فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏قَدْ مَاتَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَإِنَّهَا لَفِي كِتَابِ اللَّهِ مَا شَعَرْتُ أَنَّهَا فِي كِتَابِ اللَّهِ ثُمَّ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا أَيُّهَا النَّاسُ هَذَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَهُوَ ذُو شَيْبَةِ الْمُسْلِمِينَ فَبَايِعُوهُ فَبَايَعُوهُ ‏","","",""],[24659,24659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏مِنْ صُوفٍ عَلَيْهِ بَعْضُهُ وَعَلَيْهَا بَعْضُهُ ‏","","",""],[24660,24660,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ ‏ ‏أَنَا سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ضَحَّى اشْتَرَى كَبْشَيْنِ عَظِيمَيْنِ سَمِينَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏مَوْجُوأَيْنِ ‏ ‏قَالَ فَيَذْبَحُ أَحَدَهُمَا عَنْ أُمَّتِهِ مِمَّنْ أَقَرَّ بِالتَّوْحِيدِ وَشَهِدَ لَهُ بِالْبَلَاغِ وَيَذْبَحُ الْآخَرَ عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏وَآلِ ‏ ‏مُحَمَّدٍ ‏","","",""],[24661,24661,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى شَيْءٍ أَسْرَعُ مِنْهُ إِلَى رَكْعَتَيْنِ قَبْلَ الْفَجْرِ وَلَا إِلَى ‏ ‏غَنِيمَةٍ ‏","","",""],[24662,24662,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَطْيَبَ مَا أَكَلَ الرَّجُلُ مِنْ كَسْبِهِ وَإِنَّ وَلَدَهُ مِنْ كَسْبِهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[24663,24663,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[24664,24664,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ السُّدِّيِّ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏مَوْلَى ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏ ‏و قَالَ ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏وَقَالَ مَرَّةً ‏ ‏السُّدِّيُّ ‏ ‏أَوْ ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏وَذَاكَ أَنَّ ابْنَهُ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏قَالَ لَهُ فِي الْبَيْتِ إِنَّهُمْ يَذْكُرُونَهُ عَنْكَ عَنْ ‏ ‏السُّدِّيِّ ‏ ‏فَقَالَ ‏ ‏السُّدِّيِّ ‏ ‏أَوْ ‏ ‏زِيَادٍ ‏","","",""],[24665,24665,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ ‏","","",""],[24666,24666,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ ‏","","",""],[24667,24667,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَلَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَفَعَتْهُ قَالَتْ قَالَ ‏ ‏صَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ غَيْرَ مُتَرَبِّعٍ ‏","","",""],[24668,24668,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏زَعَمَ ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏يُخْبِرُ قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُخْبِرُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَمْكُثُ عِنْدَ ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏وَيَشْرَبُ عِنْدَهَا عَسَلًا ‏ ‏فَتَوَاصَيْتُ ‏ ‏أَنَا ‏ ‏وَحَفْصَةُ ‏ ‏أَنَّ أَيَّتَنَا مَا دَخَلَ عَلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْتَقُلْ إِنِّي أَجِدُ مِنْكَ رِيحَ ‏ ‏مَغَافِيرَ ‏ ‏أَكَلْتَ ‏ ‏مَغَافِيرَ ‏ ‏فَدَخَلَ عَلَى إِحْدَاهُمَا فَقَالَتْ ذَلِكَ لَهُ فَقَالَ بَلْ شَرِبْتُ عَسَلًا عِنْدَ ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏وَلَنْ أَعُودَ لَهُ فَنَزَلَتْ ‏ { ‏لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ ‏} { ‏إِنْ تَتُوبَا ‏} ‏لِعَائِشَةَ ‏ ‏وَحَفْصَةَ ‏ { ‏وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ ‏} ‏لِقَوْلِهِ بَلْ شَرِبْتُ عَسَلًا ‏","","",""],[24669,24669,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ إِلَى صَلَاةِ الْفَجْرِ وَرَأْسُهُ يَقْطُرُ مِنْ غُسْلِ الْجَنَابَةِ ثُمَّ يُتِمُّ صَوْمَهُ ذَلِكَ الْيَوْمَ ‏","","",""],[24670,24670,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَفْلَحُ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَقَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعْضِ نِسَائِهِ ثُمَّ نَامَ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏حَتَّى أَصْبَحَ ثُمَّ اغْتَسَلَ وَصَامَ يَوْمَهُ ‏","","",""],[24671,24671,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُحَمَّدَ بْنَ قَيْسِ بْنِ مَخْرَمَةَ بْنِ الْمُطَّلِبِ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَوْمًا أَلَا أُحَدِّثُكُمْ عَنِّي وَعَنْ أُمِّي فَظَنَنَّا أَنَّهُ يُرِيدُ أُمَّهُ الَّتِي وَلَدَتْهُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَلَا أُحَدِّثُكُمْ عَنِّي وَعَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَ قَالَتْ لَمَّا كَانَتْ لَيْلَتِي الَّتِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا عِنْدِي انْقَلَبَ فَوَضَعَ رِدَاءَهُ وَخَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عِنْدَ رِجْلَيْهِ وَبَسَطَ طَرَفَ ‏ ‏إِزَارِهِ ‏ ‏عَلَى فِرَاشِهِ فَاضْطَجَعَ فَلَمْ يَلْبَثْ إِلَّا ‏ ‏رَيْثَمَا ‏ ‏ظَنَّ أَنِّي قَدْ رَقَدْتُ فَأَخَذَ رِدَاءَهُ رُوَيْدًا وَانْتَعَلَ رُوَيْدًا وَفَتَحَ الْبَابَ فَخَرَجَ ثُمَّ ‏ ‏أَجَافَهُ ‏ ‏رُوَيْدًا فَجَعَلْتُ دِرْعِي فِي رَأْسِي ‏ ‏وَاخْتَمَرْتُ ‏ ‏وَتَقَنَّعْتُ ‏ ‏إِزَارِي ‏ ‏ثُمَّ انْطَلَقْتُ عَلَى أَثَرِهِ حَتَّى جَاءَ ‏ ‏الْبَقِيعَ ‏ ‏فَقَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَفَعَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ انْحَرَفَ فَأَسْرَعَ فَأَسْرَعْتُ فَهَرْوَلَ فَهَرْوَلْتُ ‏ ‏فَأَحْضَرَ ‏ ‏فَأَحْضَرْتُ ‏ ‏فَسَبَقْتُهُ فَدَخَلْتُ فَلَيْسَ إِلَّا أَنْ اضْطَجَعْتُ فَدَخَلَ فَقَالَ مَا لَكِ يَا ‏ ‏عَائِشُ ‏ ‏حَشْيَاءَ ‏ ‏رَائِبَةً ‏ ‏قَالَتْ قُلْتُ لَا شَيْءَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لَتُخْبِرِنَّنِي أَوْ لَيُخْبِرَنِّي اللَّطِيفُ الْخَبِيرُ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي فَأَخْبَرَتْهُ قَالَ فَأَنْتِ ‏ ‏السَّوَادُ ‏ ‏الَّذِي رَأَيْتُ أَمَامِي قُلْتُ نَعَمْ ‏ ‏فَلَهَزَنِي ‏ ‏فِي ظَهْرِي ‏ ‏لَهْزَةً ‏ ‏فَأَوْجَعَتْنِي وَقَالَ أَظَنَنْتِ أَنْ ‏ ‏يَحِيفَ ‏ ‏عَلَيْكِ اللَّهُ وَرَسُولُهُ قَالَتْ مَهْمَا ‏ ‏يَكْتُمِ النَّاسُ يَعْلَمْهُ اللَّهُ قَالَ نَعَمْ فَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَانِي حِينَ رَأَيْتِ فَنَادَانِي فَأَخْفَاهُ مِنْكِ فَأَجَبْتُهُ خُفْيَتَهُ مِنْكِ وَلَمْ يَكُنْ لِيَدْخُلَ عَلَيْكِ وَقَدْ وَضَعْتِ ثِيَابَكِ وَظَنَنْتُ أَنَّكِ قَدْ رَقَدْتِ فَكَرِهْتُ أَنْ أُوقِظَكِ وَخَشِيتُ أَنْ ‏ ‏تَسْتَوْحِشِي ‏ ‏فَقَالَ إِنَّ رَبَّكَ جَلَّ وَعَزَّ يَأْمُرُكَ أَنْ تَأْتِيَ أَهْلَ ‏ ‏الْبَقِيعِ ‏ ‏فَتَسْتَغْفِرَ لَهُمْ قَالَتْ فَكَيْفَ أَقُولُ يَا رَسُولَ اللَّهِ فَقَالَ قُولِي ‏ ‏السَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنْ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ ‏","","",""],[24672,24672,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ إِسْحَاقَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏اشْتَكَى ‏ ‏أَصْحَابُهُ وَاشْتَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعَامِرُ بْنُ فُهَيْرَةَ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَبِلَالٌ ‏ ‏فَاسْتَأْذَنَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِشَةُ ‏ ‏فِي عِيَادَتِهِمْ فَأَذِنَ لَهَا فَقَالَتْ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏كَيْفَ تَجِدُكَ فَقَالَ ‏ ‏كُلُّ امْرِئٍ مُصَبَّحٌ فِي أَهْلِهِ ‏ ‏وَالْمَوْتُ أَدْنَى مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ ‏ ‏وَسَأَلْتُ ‏ ‏عَامِرًا ‏ ‏فَقَالَ ‏ ‏وَجَدْتُ الْمَوْتَ قَبْلَ ‏ ‏ذَوْقِهِ ‏ ‏إِنَّ الْجَبَانَ ‏ ‏حَتْفُهُ ‏ ‏مِنْ فَوْقِهِ ‏ ‏وَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏فَقَالَ ‏ ‏أَلَا لَيْتَ شِعْرِي هَلْ أَبِيتَنَّ لَيْلَةً ‏ ‏بِفَجٍّ وَحَوْلِي إِذْخِرٌ ‏ ‏وَجَلِيلُ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِقَوْلِهِمْ فَنَظَرَ إِلَى السَّمَاءِ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ حَبِّبْ إِلَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏كَمَا حَبَّبْتَ إِلَيْنَا ‏ ‏مَكَّةَ ‏ ‏وَأَشَدَّ وَبَارِكْ لَنَا فِي ‏ ‏صَاعِهَا ‏ ‏وَمُدِّهَا ‏ ‏وَانْقُلْ وَبَاءَهَا إِلَى ‏ ‏مَهْيَعَةٍ ‏ ‏وَهِيَ ‏ ‏الْجُحْفَةُ ‏ ‏كَمَا زَعَمُوا ‏","","",""],[24673,24673,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي كُلَّ لَيْلَةٍ ثَلَاثَ عَشْرَةَ رَكْعَةً تِسْعًا قَائِمًا وَرَكْعَتَيْنِ وَهُوَ جَالِسٌ ثُمَّ يُمْهِلُ حَتَّى يُؤَذَّنَ بِالْأُولَى مِنْ الصُّبْحِ فَيَرْكَعُ رَكْعَتَيْنِ ‏","","",""],[24674,24674,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً بِاللَّيْلِ مَعَ رَكْعَتَيْ الْفَجْرِ ‏","","",""],[24675,24675,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الدَّمِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَدْ رَأَيْتُ ‏ ‏مِرْكَنَهَا ‏ ‏مَلْآنًا دَمًا فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ ثُمَّ اغْتَسِلِي وَصَلِّي ‏","","",""],[24676,24676,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قيسِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَنِي سَرَاةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَجْنَبَ يَغْسِلُ رَأْسَهُ بِغُسْلٍ ‏ ‏يَجْتَزِئُ ‏ ‏بِذَلِكَ أَمْ يُفِيضُ الْمَاءَ عَلَى رَأْسِهِ قَالَتْ بَلْ يُفِيضُ الْمَاءَ عَلَى رَأْسِهِ ‏","","",""],[24677,24677,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْعَبَّاسِ بْنِ ذَرِيحٍ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏عَثَرَ ‏ ‏بِأُسْكُفَّةِ ‏ ‏أَوْ عَتَبَةِ الْبَابِ ‏ ‏فَشُجَّ فِي جَبْهَتِهِ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِيطِي ‏ ‏عَنْهُ ‏ ‏أَوْ نَحِّي عَنْهُ ‏ ‏الْأَذَى قَالَتْ فَتَقَذَّرْتُهُ قَالَتْ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمُصُّهُ ثُمَّ ‏ ‏يَمُجُّهُ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ ‏ ‏أُسَامَةُ ‏ ‏جَارِيَةً لَكَسَوْتُهُ وَحَلَّيْتُهُ حَتَّى أُنْفِقَهُ ‏","","",""],[24678,24678,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَمَثَّلُ ‏ ‏الشِّعْرَ قَالَتْ ‏ ‏رُبَّمَا ‏ ‏تَمَثَّلَ ‏ ‏شِعْرَ ‏ ‏ابْنِ رَوَاحَةَ ‏ ‏وَيَقُولُ ‏ ‏وَيَأْتِيكَ بِالْأَخْبَارِ مِنْ لَمْ ‏ ‏تُزَوِّدِ ‏","","",""],[24679,24679,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏الْحَارِثِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْدُو ‏ ‏قَالَتْ نَعَمْ إِلَى هَذِهِ ‏ ‏التِّلَاعِ ‏ ‏قَالَتْ ‏ ‏فَبَدَا ‏ ‏مَرَّةً فَبَعَثَ إِلَيَّ نَعَمَ الصَّدَقَةِ فَأَعْطَانِي نَاقَةً مُحَرَّمَةً ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏لَمْ تُرْكَبْ ‏ ‏وَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏عَلَيْكِ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ وَالرِّفْقِ فَإِنَّ الرِّفْقَ لَمْ يَكُ فِي شَيْءٍ إِلَّا زَانَهُ وَلَمْ يُنْزَعْ الرِّفْقُ مِنْ شَيْءٍ إِلَّا ‏ ‏شَانَهُ ‏","","",""],[24680,24680,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى ‏ ‏نَاشِئًا ‏ ‏فِي السَّمَاءِ سَحَابًا أَوْ رِيحًا اسْتَقْبَلَهُ مِنْ حَيْثُ كَانَ وَإِنْ كَانَ فِي الصَّلَاةِ يَتَعَوَّذُ بِاللَّهِ عَزَّ وَجَلَّ مِنْ شَرِّهِ فَإِذَا أَمْطَرَتْ قَالَ اللَّهُمَّ ‏ ‏صَيِّبًا ‏ ‏نَافِعًا ‏","","",""],[24681,24681,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏قَالَ وَقَالَ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ قَالَتْ ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَ إِلَى ‏ ‏خَدِيجَةَ ‏ ‏يَرْجُفُ فُؤَادُهُ فَدَخَلَ فَقَالَ ‏ ‏زَمِّلُونِي ‏ ‏زَمِّلُونِي ‏ ‏فَزُمِّلَ فَلَمَّا ‏ ‏سُرِّيَ ‏ ‏عَنْهُ قَالَ يَا ‏ ‏خَدِيجَةُ ‏ ‏لَقَدْ أَشْفَقْتُ عَلَى نَفْسِي ‏ ‏بَلَاءً ‏ ‏لَقَدْ أَشْفَقْتُ عَلَى نَفْسِي ‏ ‏بَلَاءً ‏ ‏قَالَتْ ‏ ‏خَدِيجَةُ ‏ ‏أَبْشِرْ فَوَاللَّهِ لَا يُخْزِيكَ اللَّهُ أَبَدًا إِنَّكَ لَتَصْدُقُ الْحَدِيثَ وَتَصِلُ الرَّحِمَ وَتَحْمِلُ ‏ ‏الْكَلَّ ‏ ‏وَتَقْرِي ‏ ‏الضَّيْفَ وَتُعِينُ عَلَى ‏ ‏نَوَائِبِ ‏ ‏الْحَقِّ فَانْطَلَقَتْ بِي ‏ ‏خَدِيجَةُ ‏ ‏إِلَى ‏ ‏وَرَقَةَ بْنِ نَوْفَلِ بْنِ أَسَدٍ ‏ ‏وَكَانَ رَجُلًا قَدْ ‏ ‏تَنَصَّرَ ‏ ‏شَيْخًا أَعْمَى يَقْرَأُ الْإِنْجِيلَ بِالْعَرَبِيَّةِ فَقَالَتْ لَهُ ‏ ‏خَدِيجَةُ ‏ ‏أَيْ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ فَقَالَ لَهُ ‏ ‏وَرَقَةُ ‏ ‏يَا ابْنَ أَخِي مَاذَا ‏ ‏تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالَّذِي رَأَى مِنْ ذَلِكَ فَقَالَ لَهُ ‏ ‏وَرَقَةُ ‏ ‏هَذَا ‏ ‏النَّامُوسُ ‏ ‏الَّذِي نَزَلَ عَلَى ‏ ‏مُوسَى ‏ ‏يَا لَيْتَنِي فِيهَا ‏ ‏جَذَعًا ‏ ‏يَا لَيْتَنِي أَكُونُ حَيًّا حِينَ يُخْرِجُكَ قَوْمُكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَ مُخْرِجِيَّ هُمْ قَالَ نَعَمْ لَمْ يَأْتِ رَجُلٌ بِمِثْلِ مَا جِئْتَ بِهِ قَطُّ إِلَّا عُودِيَ وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا ‏ ‏مُؤَزَّرًا ‏","","",""],[24682,24682,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنَّ يَخْرُجْنَ بِاللَّيْلِ إِذَا ‏ ‏تَبَرَّزْنَ ‏ ‏إِلَى ‏ ‏الْمَنَاصِعِ ‏ ‏وَهُوَ ‏ ‏صَعِيدٌ ‏ ‏أَفْيَحُ ‏ ‏وَكَانَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَقُولُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْجُبْ ‏ ‏نِسَاءَكَ فَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ فَخَرَجَتْ ‏ ‏سَوْدَةُ بِنْتُ زَمْعَةَ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً مِنْ اللَّيَالِي عِشَاءً وَكَانَتْ امْرَأَةً طَوِيلَةً فَنَادَاهَا ‏ ‏عُمَرُ ‏ ‏أَلَا قَدْ عَرَفْنَاكِ يَا ‏ ‏سَوْدَةُ ‏ ‏حِرْصًا عَلَى أَنْ يُنْزَلَ الْحِجَابُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَأُنْزِلَ الْحِجَابُ ‏","","",""],[24683,24683,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَهَا وَهُوَ صَائِمٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ ‏","","",""],[24684,24684,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَصْحَابَ هَذِهِ الصُّوَرِ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ وَيُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[24685,24685,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ ‏ ‏تَقُولُ ‏ ‏مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبِّحُ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى وَكَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تُسَبِّحُهَا وَكَانَتْ تَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ كَثِيرًا مِنْ الْعَمَلِ خَشْيَةَ أَنْ ‏ ‏يَسْتَنَّ ‏ ‏النَّاسُ بِهِ فَيُفْرَضَ عَلَيْهِمْ ‏","","",""],[24686,24686,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏وَاللَّهِ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا أَخَذَ أَيْسَرَهُمَا مَا لَمْ يَأْثَمْ فَإِذَا كَانَ الْإِثْمُ كَانَ أَبْعَدَهُمْ مِنْهُ وَاللَّهِ مَا انْتَقَمَ لِنَفْسِهِ فِي شَيْءٍ يُؤْتَى إِلَيْهِ قَطُّ حَتَّى ‏ ‏تُنْتَهَكَ ‏ ‏حُرُمَاتُ اللَّهِ عَزَّ وَجَلَّ فَيَنْتَقِمَ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[24687,24687,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رُبَّمَا ‏ ‏فَتَلْتُ ‏ ‏الْقَلَائِدَ ‏ ‏لِهَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُقَلِّدُ ‏ ‏هَدْيَهُ ‏ ‏ثُمَّ يَبْعَثُ بِهِ ثُمَّ ‏ ‏يُقِيمُ ‏ ‏لَا يَجْتَنِبُ شَيْئًا مِمَّا يَجْتَنِبُ الْمُحْرِمُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏","","",""],[24688,24688,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفَارِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُهِلُّ ‏","","",""],[24689,24689,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَفِيَّةَ ‏ ‏قَالَتْ فَقُلْنَا قَدْ حَاضَتْ قَالَتْ فَقَالَ ‏ ‏عَقْرَى ‏ ‏حَلْقَى ‏ ‏مَا أُرَاهَا إِلَّا ‏ ‏حَابِسَتَنَا ‏ ‏قَالَتْ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّهَا قَدْ طَافَتْ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قَالَ فَلَا إِذًا مُرُوهَا ‏ ‏فَلْتَنْفِرْ ‏","","",""],[24690,24690,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ‏ ‏بِلَالٌ ‏ ‏يُؤْذِنُهُ بِالصَّلَاةِ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏وَإِنَّهُ مَتَى يَقُومُ مَقَامَكَ لَا يُسْمِعُ النَّاسَ فَلَوْ أَمَرْتَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ فَقُلْتُ ‏ ‏لِحَفْصَةَ ‏ ‏قُولِي لَهُ فَقَالَتْ لَهُ ‏ ‏حَفْصَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏وَإِنَّهُ مَتَى يَقُومُ مَقَامَكَ لَا يُسْمِعُ النَّاسَ فَلَوْ أَمَرْتَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ إِنَّكُنَّ لَأَنْتُنَّ صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ فَأَمَرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ فَلَمَّا دَخَلَ فِي الصَّلَاةِ وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَفْسِهِ خِفَّةً فَقَالَتْ فَقَامَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ رَجُلَيْنِ وَرِجْلَاهُ ‏ ‏تَخُطَّانِ ‏ ‏فِي الْأَرْضِ حَتَّى دَخَلَ الْمَسْجِدَ فَلَمَّا سَمِعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حِسَّهُ ذَهَبَ لِيَتَأَخَّرَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ قُمْ كَمَا أَنْتَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَلَسَ عَنْ يَسَارِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ قَاعِدًا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏قَائِمًا ‏ ‏يَقْتَدِي ‏ ‏أَبُو بَكْرٍ ‏ ‏بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ يَقْتَدُونَ بِصَلَاةِ ‏ ‏أَبِي بَكْرٍ ‏","","",""],[24691,24691,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏نَذَرَ ‏ ‏أَنْ يُطِيعَ اللَّهَ عَزَّ وَجَلَّ فَلْيُطِعْهُ وَمَنْ ‏ ‏نَذَرَ ‏ ‏أَنْ يَعْصِيَ اللَّهَ عَزَّ وَجَلَّ فَلَا يَعْصِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏وَأَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدِيثٌ غَرِيبٌ مِنْ حَدِيثِ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏مَا سَمِعْتُهُ إِلَّا مِنْ أَبِي عَنْ ‏ ‏ابْنِ نُمَيْرٍ ‏ ‏وَطَلْحَةَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏أَيْلَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ أَصْحَابُ الْحَدِيثِ لَيْسَ هَذَا ‏ ‏بِالْكُوفَةِ ‏ ‏إِنَّمَا هَذَا عَنْ ‏ ‏ابْنِ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏فَقُلْتُ لَهُمْ امْضُوا إِلَى ‏ ‏أَبِي خَيْثَمَةَ ‏ ‏فَإِنَّ سَمَاعَهُمْ ‏ ‏بِالْكُوفَةِ ‏ ‏وَاحِدٌ مِنْ ‏ ‏ابْنِ نُمَيْرٍ ‏ ‏فَذَهَبُوا فَأَصَابُوهُ ‏","","",""],[24692,24692,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجْنِبُ مِنْ اللَّيْلِ ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ حَتَّى يُصْبِحَ وَلَا يَمَسُّ مَاءً ‏","","",""],[24693,24693,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَقْرَأُ عَلَيْكِ السَّلَامَ قَالَتْ فَقُلْتُ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ ‏","","",""],[24694,24694,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ حَسَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏دِقْرَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَمْشِي مَعَ ‏ ‏عَائِشَةَ ‏ ‏فِي نِسْوَةٍ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَرَأَيْتُ امْرَأَةً عَلَيْهَا ‏ ‏خَمِيصَةٌ ‏ ‏فِيهَا ‏ ‏صُلُبٌ ‏ ‏فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏انْزَعِي هَذَا مِنْ ثَوْبِكِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَآهُ فِي ثَوْبٍ ‏ ‏قَضَبَهُ ‏","","",""],[24695,24695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏حَسَنِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشِيقَةُ ‏ ‏ظَبْيٍ وَهُوَ مُحْرِمٌ فَلَمْ يَأْكُلْهُ ‏","","",""],[24696,24696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ يَدْعُو حَتَّى إِنِّي ‏ ‏لَأَسْأَمُ ‏ ‏لَهُ مِمَّا يَرْفَعُهُمَا يَدْعُو ‏ ‏اللَّهُمَّ فَإِنَّمَا أَنَا بَشْرٌ فَلَا تُعَذِّبْنِي بِشَتْمِ رَجُلٍ شَتَمْتُهُ أَوْ آذَيْتُهُ ‏","","",""],[24697,24697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَإِسْحَاقُ يَعْنِي ابْنَ عِيسَى الطَّبَّاعَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَنَامُ بَيْنَ يَدَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِجْلَيَّ فِي قِبْلَتِهِ ‏ ‏فَإِذَا أَرَادَ أَنْ يَسْجُدَ غَمَزَنِي فَقَبَضْتُ رِجْلَيَّ فَإِذَا قَامَ بَسَطْتُهَا قَالَتْ وَلَمْ يَكُنْ فِي الْبُيُوتِ يَوْمَئِذٍ مَصَابِيحُ ‏","","",""],[24698,24698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا لَمْ تَكُنْ تَفْعَلُ ذَلِكَ وَقَالَتْ ‏ ‏إِنَّمَا نَزَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَنَّهُ كَانَ مَنْزِلًا أَسْمَحَ لِخُرُوجِهِ ‏","","",""],[24699,24699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ أَنْ يُضَحِّيَ اشْتَرَى كَبْشَيْنِ عَظِيمَيْنِ سَمِينَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏أَقْرَنَيْنِ ‏ ‏مَوْجُوأَيْنِ ‏ ‏فَيَذْبَحُ أَحَدَهُمَا عَنْ أُمَّتِهِ مِمَّنْ شَهِدَ بِالتَّوْحِيدِ وَشَهِدَ لَهُ بِالْبَلَاغِ وَذَبَحَ الْآخَرَ عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَآلِ ‏ ‏مُحَمَّدٍ ‏","","",""],[24700,24700,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَبْعَثُ بِهَا فَمَا يَجْتَنِبُ شَيْئًا مِمَّا يَجْتَنِبُ الْمُحْرِمُ ‏","","",""],[24701,24701,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏هِنْدٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ مَا كَانَ عَلَى ظَهْرِ الْأَرْضِ ‏ ‏خِبَاءٌ ‏ ‏أَحَبُّ إِلَيَّ أَنْ يُذِلَّهُمْ اللَّهُ عَزَّ وَجَلَّ مِنْ أَهْلِ ‏ ‏خِبَائِكَ ‏ ‏وَمَا عَلَى ظَهْرِ الْأَرْضِ الْيَوْمَ أَهْلُ ‏ ‏خِبَاءٍ ‏ ‏أَحَبُّ إِلَيَّ أَنْ يُعِزَّهُمْ اللَّهُ عَزَّ وَجَلَّ مِنْ أَهْلِ ‏ ‏خِبَائِكَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَيْضًا وَالَّذِي نَفْسِي بِيَدِهِ ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أَبَا سُفْيَانَ ‏ ‏رَجُلٌ مُمْسِكٌ فَهَلْ عَلَيَّ حَرَجٌ أَنْ أُنْفِقَ عَلَى عِيَالِهِ مِنْ مَالِهِ بِغَيْرِ إِذْنِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَرَجَ عَلَيْكِ أَنْ تُنْفِقِي عَلَيْهِمْ بِالْمَعْرُوفِ ‏","","",""],[24702,24702,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الجَزَّارِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ تِسْعًا فَلَمَّا ثَقُلَ وَأَسَنَّ صَلَّى سَبْعًا ‏","","",""],[24703,24703,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَسَرَّ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِرَاءَةَ فِي رَكْعَتَيْ الْفَجْرِ وَقَرَأَ فِيهِمَا ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[24704,24704,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏الْبِتْعِ ‏ ‏فَقَالَ ‏ ‏كُلُّ شَرَابٍ يُسْكِرُ فَهُوَ حَرَامٌ ‏ ‏وَالْبِتْعُ ‏ ‏نَبِيذُ ‏ ‏الْعَسَلِ ‏","","",""],[24705,24705,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏رِفَاعَةَ الْقُرَظِيَّ ‏ ‏طَلَّقَ امْرَأَتَهُ ‏ ‏فَبَتَّ ‏ ‏طَلَاقَهَا فَتَزَوَّجَهَا بَعْدَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الزُّبَيْرِ ‏ ‏فَجَاءَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا نَبِيَّ اللَّهِ ‏ ‏إِنَّهَا كَانَتْ عِنْدَ ‏ ‏رِفَاعَةَ ‏ ‏وَطَلَّقَهَا آخِرَ ثَلَاثِ تَطْلِيقَاتٍ فَتَزَوَّجَتْ بَعْدَهُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الزُّبَيْرِ ‏ ‏وَإِنَّهُ وَاللَّهِ مَا مَعَهُ يَا رَسُولَ اللَّهِ إِلَّا مِثْلَ هَذِهِ الْهُدْبَةِ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَهَا لَعَلَّكِ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى ‏ ‏رِفَاعَةَ ‏ ‏لَا حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ قَالَتْ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏جَالِسٌ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَالِدُ بْنُ سَعِيدٍ ‏ ‏جَالِسٌ بِبَابِ الْحُجْرَةِ لَمْ يُؤْذَنْ لَهُ ‏ ‏فَطَفِقَ ‏ ‏خَالِدٌ ‏ ‏يُنَادِي ‏ ‏أَبَا بَكْرٍ ‏ ‏يَقُولُ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَلَا تَزْجُرُ هَذِهِ عَمَّا تَجْهَرُ بِهِ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24706,24706,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏دَخَلَتْ امْرَأَةُ ‏ ‏عُثْمَانَ بْنِ مَظْعُونٍ ‏ ‏أَحْسِبُ اسْمَهَا ‏ ‏خَوْلَةَ بِنْتَ حَكِيمٍ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَهِيَ ‏ ‏بَاذَّةُ ‏ ‏الْهَيْئَةِ فَسَأَلْتُهَا مَا شَأْنُكِ فَقَالَتْ زَوْجِي يَقُومُ اللَّيْلَ وَيَصُومُ النَّهَارَ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ‏ ‏عَائِشَةُ ‏ ‏ذَلِكَ لَهُ فَلَقِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُثْمَانَ ‏ ‏فَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏إِنَّ الرَّهْبَانِيَّةَ لَمْ تُكْتَبْ عَلَيْنَا أَفَمَا لَكَ فِيَّ أُسْوَةٌ فَوَاللَّهِ إِنِّي ‏ ‏أَخْشَاكُمْ لِلَّهِ وَأَحْفَظُكُمْ لِحُدُودِهِ ‏","","",""],[24707,24707,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏عُتْبَةَ بْنَ أَبِي وَقَّاصٍ ‏ ‏قَالَ لِأَخِيهِ ‏ ‏سَعْدٍ ‏ ‏أَتَعْلَمُ أَنَّ ابْنَ جَارِيَةِ ‏ ‏زَمْعَةَ ‏ ‏ابْنِي قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَمَّا كَانَ يَوْمُ الْفَتْحِ رَأَى ‏ ‏سَعْدٌ ‏ ‏الْغُلَامَ فَعَرَفَهُ بِالشَّبَهِ وَاحْتَضَنَهُ إِلَيْهِ وَقَالَ ابْنُ أَخِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَاءَ ‏ ‏عَبْدُ بْنُ زَمْعَةَ ‏ ‏فَقَالَ بَلْ هُوَ أَخِي وَوُلِدَ عَلَى فِرَاشِ أَبِي مِنْ جَارِيَتِهِ فَانْطَلَقَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا رَسُولَ اللَّهِ هَذَا ابْنُ أَخِي انْظُرْ إِلَى شَبَهِهِ ‏ ‏بِعُتْبَةَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَرَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَبَهًا لَمْ يَرَ النَّاسُ شَبَهًا أَبْيَنَ مِنْهُ ‏ ‏بِعُتْبَةَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ بْنُ زَمْعَةَ ‏ ‏يَا رَسُولَ اللَّهِ بَلْ هُوَ أَخِي وُلِدَ عَلَى فِرَاشِ أَبِي مِنْ جَارِيَتِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَدُ لِلْفِرَاشِ وَاحْتَجِبِي عَنْهُ يَا ‏ ‏سَوْدَةُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَوَاللَّهِ مَا رَآهَا حَتَّى مَاتَتْ ‏","","",""],[24708,24708,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏مَسْرُورًا فَقَالَ أَلَمْ تَسْمَعِي مَا قَالَ ‏ ‏الْمُدْلِجِيُّ ‏ ‏وَرَأَى ‏ ‏أُسَامَةَ ‏ ‏وَزَيْدًا ‏ ‏نَائِمَيْنِ فِي ثَوْبٍ أَوْ فِي ‏ ‏قَطِيفَةٍ ‏ ‏وَقَدْ خَرَجَتْ أَقْدَامُهُمَا فَقَالَ ‏ ‏إِنَّ هَذِهِ الْأَقْدَامَ بَعْضُهَا مِنْ بَعْضٍ ‏","","",""],[24709,24709,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏تَبْرُقُ ‏ ‏أَسَارِيرُ ‏ ‏وَجْهِهِ ‏","","",""],[24710,24710,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ ‏ ‏يَعْتَكِفَ ‏ ‏صَلَّى الصُّبْحَ ثُمَّ دَخَلَ فِي الْمَكَانِ الَّذِي يُرِيدُ أَنْ ‏ ‏يَعْتَكِفَ ‏ ‏فِيهِ فَأَرَادَ أَنْ ‏ ‏يَعْتَكِفَ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ فَأَمَرَ فَضُرِبَ لَهُ ‏ ‏خِبَاءٌ ‏ ‏وَأَمَرَتْ ‏ ‏عَائِشَةُ ‏ ‏فَضُرِبَ لَهَا ‏ ‏خِبَاءٌ ‏ ‏وَأَمَرَتْ ‏ ‏حَفْصَةُ ‏ ‏فَضُرِبَ لَهَا ‏ ‏خِبَاءٌ ‏ ‏فَلَمَّا رَأَتْ ‏ ‏زَيْنَبُ ‏ ‏خِبَاءَهُمَا أَمَرَتْ فَضُرِبَ لَهَا ‏ ‏خِبَاءٌ ‏ ‏فَلَمَّا رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ قَالَ ‏ ‏الْبِرُّ ‏ ‏تُرِدْنَ فَلَمْ ‏ ‏يَعْتَكِفْ ‏ ‏فِي رَمَضَانَ ‏ ‏وَاعْتَكَفَ ‏ ‏عَشْرًا مِنْ شَوَّالٍ ‏","","",""],[24711,24711,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَائِلُ بْنُ دَاوُدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَهِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْدَ بْنَ حَارِثَةَ ‏ ‏فِي جَيْشٍ قَطُّ إِلَّا ‏ ‏أَمَّرَهُ عَلَيْهِمْ وَلَوْ بَقِيَ بَعْدَهُ اسْتَخْلَفَهُ ‏","","",""],[24712,24712,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي الصَّلْتِ ‏ ‏أَنَّ ‏ ‏عِرَاكَ بْنَ مَالِكٍ ‏ ‏حَدَّثَ ‏ ‏عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ نَاسًا يَكْرَهُونَ أَنْ يَسْتَقْبِلُوا الْقِبْلَةَ بِفُرُوجِهِمْ فَقَالَ ‏ ‏أَوَ قَدْ فَعَلُوهَا ‏ ‏حَوِّلُوا مَقْعَدِي قِبَلَ الْقِبْلَةِ ‏","","",""],[24713,24713,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُوتِرُ بِتِسْعِ رَكَعَاتٍ فَلَمَّا بَدَّنَ وَلَحُمَ صَلَّى سَبْعَ رَكَعَاتٍ ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَلَمَّا لَحُمَ وَبَدَّنَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[24714,24714,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا الْتَقَى الْخِتَانَانِ اغْتَسَلَ ‏","","",""],[24715,24715,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُهَاجِرٍ الْجَبَلِيُّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏أَنَّ ‏ ‏السَّائِبَ ‏ ‏سَأَلَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ إِنِّي لَا أَسْتَطِيعُ أَنْ أُصَلِّيَ إِلَّا جَالِسًا فَكَيْفَ تَرَيْنَ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةُ الرَّجُلِ جَالِسًا مِثْلُ نِصْفِ صَلَاتِهِ قَائِمًا ‏","","",""],[24716,24716,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏بُدَيْلُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا ‏","","",""],[24717,24717,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَرَأَيْتِ قَوْلَ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ ‏ ‏شَعَائِرِ ‏ ‏اللَّهِ فَمَنْ حَجَّ ‏ ‏الْبَيْتَ ‏ ‏أَوْ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏} ‏وَاللَّهِ مَا عَلَى أَحَدٍ جُنَاحٌ أَنْ لَا يَطَّوَّفَ بِهِمَا قَالَتْ بِئْسَمَا قُلْتَ يَا ابْنَ أُخْتِي إِنَّهَا لَوْ كَانَتْ كَمَا أَوَّلْتَهَا عَلَيْهِ كَانَتْ فَلَا جُنَاحَ عَلَيْهِ أَنْ لَا يَطَّوَّفَ بِهِمَا إِنَّمَا أُنْزِلَتْ أَنَّ هَذَا الْحَيَّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانُوا قَبْلَ أَنْ يُسْلِمُوا ‏ ‏يُهِلُّوا ‏ ‏لِمَنَاةَ الطَّاغِيَةِ الَّتِي كَانُوا يَعْبُدُونَ عِنْدَ ‏ ‏الْمُشَلَّلِ ‏ ‏وَكَانَ مَنْ أَهَلَّ لَهَا يَتَحَرَّجُ أَنْ يَطَّوَّفَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ ‏ ‏شَعَائِرِ ‏ ‏اللَّهِ فَمَنْ حَجَّ ‏ ‏الْبَيْتَ ‏ ‏أَوْ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏} ‏قَالَ ثُمَّ قَدْ ‏ ‏سَنَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّوَافَ بِهِمَا فَلَيْسَ يَنْبَغِي لِأَحَدٍ أَنْ يَدَعَ الطَّوَافَ بِهِمَا ‏","","",""],[24718,24718,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يُوتِرُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يَقْرَأُ فِي الرَّكْعَةِ الْأُولَى ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَفِي الثَّانِيَةَ ‏ ‏بِقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَفِي الثَّالِثَةِ ‏ ‏بِقُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏وَالْمُعَوِّذَتَيْنِ ‏","","",""],[24719,24719,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يُطِيلُ الصَّلَاةَ قَائِمًا وَقَاعِدًا وَكَانَ إِذَا صَلَّى قَائِمًا رَكَعَ قَائِمًا وَإِذَا صَلَّى قَاعِدًا رَكَعَ قَاعِدًا وَسَأَلْتُهَا عَنْ صِيَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ قَدْ صَامَ قَدْ صَامَ قَدْ صَامَ وَيُفْطِرُ حَتَّى نَقُولَ قَدْ أَفْطَرَ قَدْ أَفْطَرَ قَدْ أَفْطَرَ وَلَمْ يَصُمْ شَهْرًا تَامًّا مُنْذُ أَتَى ‏ ‏الْمَدِينَةَ ‏ ‏إِلَّا أَنْ يَكُونَ شَهْرَ رَمَضَانَ ‏","","",""],[24720,24720,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَجَعَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ مِنْ جَنَازَةٍ ‏ ‏بِالْبَقِيعِ ‏ ‏وَأَنَا أَجِدُ صُدَاعًا فِي رَأْسِي وَأَنَا أَقُولُ وَا ‏ ‏رَأْسَاهْ قَالَ بَلْ أَنَا وَا ‏ ‏رَأْسَاهْ قَالَ ‏ ‏مَا ضَرَّكِ لَوْ مِتِّ قَبْلِي فَغَسَّلْتُكِ وَكَفَّنْتُكِ ثُمَّ صَلَّيْتُ عَلَيْكِ وَدَفَنْتُكِ قُلْتُ لَكِنِّي ‏ ‏أَوْ لَكَأَنِّي بِكَ ‏ ‏وَاللَّهِ لَوْ فَعَلْتَ ذَلِكَ لَقَدْ رَجَعْتَ إِلَى بَيْتِي فَأَعْرَسْتَ فِيهِ بِبَعْضِ نِسَائِكَ قَالَتْ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ بُدِئَ بِوَجَعِهِ الَّذِي مَاتَ فِيهِ ‏","","",""],[24721,24721,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُسْلِمِ بْنِ يَنَّاقٍ ‏ ‏عَنْ ‏ ‏صَفِيَّهَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْهَا امْرَأَةٌ فَقَالَتْ ابْنَةٌ لِي سَقَطَ شَعْرُهَا أَفَنَجْعَلُ عَلَى رَأْسِهَا شَيْئًا نُجَمِّلُهَا بِهِ قَالَتْ سَمِعْتُ امْرَأَةً تَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مِثْلِ مَا سَأَلْتِ عَنْهُ فَقَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[24722,24722,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏مَا اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا فِي ذِي الْقِعْدَةِ وَلَقَدْ اعْتَمَرَ ثَلَاثَ عُمَرٍ ‏","","",""],[24723,24723,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَمْسٍ لُبْسِ الْحَرِيرِ وَالذَّهَبِ وَالشُّرْبِ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ ‏ ‏وَالْمِيثَرَةِ ‏ ‏الْحَمْرَاءِ وَلُبْسِ ‏ ‏الْقَسِّيِّ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ شَيْءٌ رَقِيقٌ مِنْ الذَّهَبِ يُرْبَطُ بِهِ ‏ ‏الْمِسْكُ ‏ ‏أَوْ يُرْبَطُ بِهِ ‏ ‏قَالَ لَا اجْعَلِيهِ فِضَّةً وَصَفِّرِيهِ بِشَيْءٍ مِنْ ‏ ‏زَعْفَرَانٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى قَائِمًا فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ سَلَمَةَ ‏","","",""],[24724,24724,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏سَهْلَةُ بِنْتُ سُهَيْلٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ ‏ ‏سَالِمًا ‏ ‏كَانَ يُدْعَى ‏ ‏لِأَبِي حُذَيْفَةَ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَنْزَلَ كِتَابَهُ ‏ { ‏ادْعُوهُمْ لِآبَائِهِمْ ‏} ‏فَكَانَ يَدْخُلُ عَلَيَّ وَأَنَا ‏ ‏فُضُلٌ ‏ ‏وَنَحْنُ فِي مَنْزِلٍ ضَيِّقٍ فَقَالَ أَرْضِعِي ‏ ‏سَالِمًا ‏ ‏تَحْرُمِي عَلَيْهِ ‏","","",""],[24725,24725,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏أَوَّلُ مَا ‏ ‏اشْتَكَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَاسْتَأْذَنَ أَزْوَاجَهُ أَنْ يُمَرَّضَ فِي بَيْتِهَا فَأَذِنَّ لَهُ فَخَرَجَ وَيَدٌ لَهُ عَلَى ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏وَيَدٌ لَهُ عَلَى رَجُلٍ آخَرَ وَهُوَ يَخُطُّ بِرِجْلَيْهِ فِي الْأَرْضِ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏أَتَدْرُونَ مَنْ الرَّجُلُ الْآخَرُ الَّذِي لَمْ تُسَمِّ ‏ ‏عَائِشَةُ ‏ ‏هُوَ ‏ ‏عَلِيٌّ ‏ ‏وَلَكِنَّ ‏ ‏عَائِشَةَ ‏ ‏لَا تَطِيبُ لَهُ نَفْسًا ‏","","",""],[24726,24726,"","","‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏أَوْ ‏ ‏عَمْرَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ صُبُّوا عَلَيَّ مِنْ سَبْعِ ‏ ‏قِرَبٍ ‏ ‏لَمْ تُحْلَلْ ‏ ‏أَوْكِيَتُهُنَّ ‏ ‏لَعَلِّي أَسْتَرِيحُ فَأَعْهَدَ إِلَى النَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَأَجْلَسْنَاهُ فِي ‏ ‏مِخْضَبٍ ‏ ‏لِحَفْصَةَ ‏ ‏مِنْ نُحَاسٍ وَسَكَبْنَا عَلَيْهِ الْمَاءَ مِنْهُنَّ حَتَّى ‏ ‏طَفِقَ ‏ ‏يُشِيرُ إِلَيْنَا أَنْ قَدْ فَعَلْتُنَّ ثُمَّ خَرَجَ ‏","","",""],[24727,24727,"","","‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ نَزَلَ بِهِ جَعَلَ يُلْقِي ‏ ‏خَمِيصَةً ‏ ‏لَهُ عَلَى وَجْهِهِ فَإِذَا ‏ ‏اغْتَمَّ ‏ ‏كَشَفَهَا عَنْ وَجْهِهِ وَهُوَ يَقُولُ ‏ ‏لَعْنَةُ اللَّهِ عَلَى ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ قَالَ تَقُولُ ‏ ‏عَائِشَةُ ‏ ‏يُحَذِّرُ مِثْلَ الَّذِي صَنَعُوا ‏","","",""],[24728,24728,"","","‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏حَمْزَةُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏لَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتِي قَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ رَقِيقٌ إِذَا قَرَأَ الْقُرْآنَ لَا يَمْلِكُ دَمْعَهُ فَلَوْ أَمَرْتَ غَيْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَتْ وَاللَّهِ مَا بِي إِلَّا كَرَاهِيَةُ أَنْ يَتَشَاءَمَ النَّاسُ بِأَوَّلِ مَنْ يَقُومُ فِي مَقَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَرَاجَعْتُهُ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏فَقَالَ ‏ ‏لِيُصَلِّ بِالنَّاسِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَإِنَّكُنَّ صَوَاحِبُ ‏ ‏يُوسُفَ ‏","","",""],[24729,24729,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ تَلْبِيَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ ‏","","",""],[24730,24730,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ فَقُلْتُ إِنِّي حَائِضٌ فَقَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ ‏","","",""],[24731,24731,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَلَّقَ رَجُلٌ امْرَأَتَهُ فَتَزَوَّجَتْ زَوْجًا غَيْرَهُ فَدَخَلَ بِهَا وَكَانَ مَعَهُ مِثْلُ ‏ ‏الْهُدْبَةِ ‏ ‏فَلَمْ ‏ ‏يَقْرَبْهَا ‏ ‏إِلَّا هَبَّةً وَاحِدَةً لَمْ يَصِلْ مِنْهَا إِلَى شَيْءٍ فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ أَحِلُّ لِزَوْجِي الْأَوَّلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلِّي لِزَوْجِكِ الْأَوَّلِ حَتَّى يَذُوقَ الْآخَرُ ‏ ‏عُسَيْلَتَكِ ‏ ‏وَتَذُوقِي ‏ ‏عُسَيْلَتَهُ ‏","","",""],[24732,24732,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَفَرٍ قَالَتْ فَعَلَّقْتُ عَلَى بَابِي ‏ ‏قِرَامًا ‏ ‏فِيهِ الْخَيْلُ ‏ ‏أُولَاتُ الْأَجْنِحَةِ قَالَتْ فَلَمَّا رَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ انْزِعِيهِ ‏","","",""],[24733,24733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَغْتَسِلُ وَيُتِمُّ صَوْمَهُ ‏","","",""],[24734,24734,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَرَبَ خَادِمًا لَهُ قَطُّ وَلَا امْرَأَةً لَهُ قَطُّ وَلَا ضَرَبَ بِيَدِهِ شَيْئًا قَطُّ إِلَّا أَنْ يُجَاهِدَ فِي سَبِيلِ اللَّهِ وَلَا نِيلَ مِنْهُ شَيْءٌ قَطُّ فَيَنْتَقِمَهُ مِنْ صَاحِبِهِ إِلَّا أَنْ يَكُونَ لِلَّهِ عَزَّ وَجَلَّ فَإِنْ كَانَ لِلَّهِ انْتَقَمَ لَهُ وَلَا عُرِضَ عَلَيْهِ أَمْرَانِ إِلَّا أَخَذَ بِالَّذِي هُوَ أَيْسَرُ إِلَّا أَنْ يَكُونَ إِثْمًا فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏","","",""],[24735,24735,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاسٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالُوا ‏ ‏السَّامُ ‏ ‏عَلَيْكَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ وَعَلَيْكُمْ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ وَعَلَيْكُمْ ‏ ‏السَّامُ ‏ ‏وَالذَّامُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏لَا تَكُونِي ‏ ‏فَاحِشَةً ‏ ‏قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ أَمَا سَمِعْتَ مَا قَالُوا ‏ ‏السَّامُ ‏ ‏عَلَيْكَ قَالَ أَلَيْسَ قَدْ رَدَدْتُ عَلَيْهِمْ الَّذِي قَالُوا قُلْتُ وَعَلَيْكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏يَعْنِي فِي حَدِيثِ ‏ ‏عَائِشَةَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يُحِبُّ ‏ ‏الْفُحْشَ ‏ ‏وَلَا التَّفَحُّشَ ‏ ‏وَقَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏فِي حَدِيثِهِ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَإِذَا جَاءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ ‏ ‏بِهِ اللَّهُ ‏} ‏حَتَّى فَرَغَ ‏","","",""],[24736,24736,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24737,24737,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ نُزُولَ ‏ ‏الْأَبْطَحِ ‏ ‏لَيْسَ بِسُنَّةٍ إِنَّمَا نَزَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَنَّهُ كَانَ أَسْمَحَ لِخُرُوجِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24738,24738,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَيَعْلَى ‏ ‏أَنْبَأَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْسِلُ رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏عَاكِفٌ ‏ ‏وَأَنَا حَائِضٌ ‏","","",""],[24739,24739,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَيَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا أُنْزِلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏إِلَى آخِرِهَا مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً إِلَّا قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي ‏","","",""],[24740,24740,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَحَدَّثَنَاهُ عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ بَلَغَهَا ‏ ‏أَنَّ نَاسًا يَقُولُونَ يَقْطَعُ الصَّلَاةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏عَدَلْتُمُونَا ‏ ‏بِالْكِلَابِ وَالْحَمِيرِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مُقَابِلَ السَّرِيرِ وَأَنَا عَلَيْهِ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَتَكُونُ لِي الْحَاجَةُ ‏ ‏فَأَنْسَلُّ ‏ ‏مِنْ قِبَلِ رِجْلِ السَّرِيرِ كَرَاهِيَةَ أَنْ أَسْتَقْبِلَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قُطْبَةُ ‏ ‏فَذَكَرَهُمَا جَمِيعًا وَقَالَ رِجْلَيْ السَّرِيرِ ‏","","",""],[24741,24741,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُصِيبُهُ الْجَنَابَةُ مِنْ اللَّيْلِ وَهُوَ يُرِيدُ الصِّيَامَ فَيَنَامُ وَيَسْتَيْقِظُ وَيُصْبِحُ جُنُبًا فَيُفِيضُ عَلَيْهِ مِنْ الْمَاءِ ثُمَّ يَتَوَضَّأُ ‏","","",""],[24742,24742,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ لِأَنَّهُ كَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[24743,24743,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ ‏ ‏وَبِيصَ ‏ ‏الطِّيبِ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُلَبِّي ‏","","",""],[24744,24744,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْأَسْوَدُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَهَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَهُودِيًّا ‏ ‏دِرْعًا ‏ ‏وَأَخَذَ مِنْهُ طَعَامًا ‏","","",""],[24745,24745,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنِّي لَأَعْلَمُ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي قَالَ فَكَانَتْ ‏ ‏تُلَبِّي بِهَؤُلَاءِ الْكَلِمَاتِ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ ‏","","",""],[24746,24746,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً ‏ ‏يُوتِرُ ‏ ‏مِنْ ذَلِكَ بِخَمْسٍ لَا يَجْلِسُ فِي شَيْءٍ مِنْهَا إِلَّا فِي آخِرِهَا فَإِذَا أَذَّنَ الْمُؤَذِّنُ قَامَ فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[24747,24747,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَكَّ مِنْ الْقِبْلَةِ مُخَاطًا ‏ ‏أَوْ بُصَاقًا أَوْ ‏ ‏نُخَامَةً ‏","","",""],[24748,24748,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا ‏ ‏ذَا الطُّفْيَتَيْنِ ‏ ‏فَإِنَّهُ ‏ ‏يَلْتَمِسُ ‏ ‏الْبَصَرَ وَيُصِيبُ ‏ ‏الْحَبَلَ ‏","","",""],[24749,24749,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ خَبُثَتْ نَفْسِي وَلَكِنْ لِيَقُلْ لَقِسَتْ نَفْسِي ‏","","",""],[24750,24750,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي شَيْءٍ مِنْ صَلَاةِ اللَّيْلِ جَالِسًا حَتَّى دَخَلَ فِي السِّنِّ فَكَانَ يَجْلِسُ فَيَقْرَأُ حَتَّى إِذَا ‏ ‏غَبَرَ ‏ ‏مِنْ السُّورَةِ ثَلَاثُونَ ‏ ‏أَوْ أَرْبَعُونَ ‏ ‏آيَةً قَامَ فَقَرَأَ بِهَا ثُمَّ رَكَعَ ‏","","",""],[24751,24751,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَغْتَسِلُ مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ نَغْتَرِفُ مِنْهُ جَمِيعًا ‏","","",""],[24752,24752,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ عَلَى الْفِرَاشِ الَّذِي يَرْقُدُ عَلَيْهِ هُوَ وَأَهْلُهُ فَإِذَا أَرَادَ أَنْ ‏ ‏يُوتِرَ ‏ ‏أَيْقَظَنِي ‏ ‏فَأَوْتَرْتُ ‏","","",""],[24753,24753,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ لِلنَّاسِ فِي مَرَضِهِ فَكَانَ ‏ ‏يُصَلِّي لَهُمْ ‏","","",""],[24754,24754,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ‏ ‏صَفِيَّةَ ‏ ‏فَقِيلَ إِنَّهَا حَائِضٌ فَقَالَ ‏ ‏لَعَلَّهَا حَابِسَتُنَا قِيلَ يَا رَسُولَ اللَّهِ إِنَّهَا قَدْ أَفَاضَتْ قَالَ فَلَا إِذًا ‏","","",""],[24755,24755,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ عِنْدَهَا ‏ ‏امْرَأَةٌ ‏ ‏مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ هَذِهِ قَالَتْ هَذِهِ فُلَانَةُ لَا تَنَامُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِمَا تُطِيقُونَ فَوَاللَّهِ لَا ‏ ‏يَمَلُّ ‏ ‏اللَّهُ حَتَّى ‏ ‏تَمَلُّوا ‏ ‏أَحَبُّ الدِّينِ إِلَى اللَّهِ عَزَّ وَجَلَّ الَّذِي يُدَاوِمُ عَلَيْهِ صَاحِبُهُ ‏","","",""],[24756,24756,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَقْتُلْ الْمُحْرِمُ الْفَأْرَةَ وَالْغُرَابَ وَالْحِدَأَ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏ ‏وَالْعَقْرَبَ ‏","","",""],[24757,24757,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وحَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏أَبُو أُسَامَةَ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يُتَوَفَّى وَأَنَا مُسْنِدَتُهُ إِلَى صَدْرِي يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى ‏","","",""],[24758,24758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ ‏ ‏تُرَجِّلُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏يُنَاوِلُهَا رَأْسَهُ وَهِيَ فِي حُجْرَتِهَا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ ‏","","",""],[24759,24759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُفِّنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَلَاثَةِ أَثْوَابٍ ‏ ‏سُحُولِيَّةٍ ‏ ‏بِيضٍ ‏","","",""],[24760,24760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏رَضِيعِ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عِائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ رَجُلٍ يَمُوتُ فَيُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ الْمُسْلِمِينَ ‏ ‏فَيَشْفَعُونَ ‏ ‏لَهُ إِلَّا ‏ ‏شُفِّعُوا ‏","","",""],[24761,24761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ ‏ ‏مَا بَالُ الْحَائِضِ تَقْضِي الصَّوْمَ وَلَا تَقْضِي الصَّلَاةَ فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَالَتْ قُلْتُ لَسْتُ ‏ ‏بِحَرُورِيَّةٍ ‏ ‏وَلَكِنِّي أَسْأَلُ قَالَتْ قَدْ كَانَ يُصِيبُنَا ذَلِكَ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُؤْمَرُ وَلَا نُؤْمَرُ فَيَأْمُرُ بِقَضَاءِ الصَّوْمِ وَلَا يَأْمُرُ بِقَضَاءِ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏","","",""],[24762,24762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى قَبَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[24763,24763,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ بَعْضَ نِسَائِهِ وَهُوَ صَائِمٌ ‏","","",""],[24764,24764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً فِي الْمَسْجِدِ فِي شَهْرِ رَمَضَانَ وَمَعَهُ نَاسٌ ثُمَّ صَلَّى الثَّانِيَةَ فَاجْتَمَعَ تِلْكَ اللَّيْلَةَ أَكْثَرُ مِنْ الْأُولَى فَلَمَّا كَانَتْ الثَّالِثَةُ ‏ ‏أَوْ الرَّابِعَةُ ‏ ‏امْتَلَأَ الْمَسْجِدُ حَتَّى ‏ ‏اغْتَصَّ ‏ ‏بِأَهْلِهِ فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ النَّاسُ يُنَادُونَهُ الصَّلَاةَ فَلَمْ يَخْرُجْ فَلَمَّا أَصْبَحَ قَالَ لَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مَا زَالَ النَّاسُ يَنْتَظِرُونَكَ الْبَارِحَةَ يَا رَسُولَ اللَّهِ قَالَ أَمَا إِنَّهُ لَمْ يَخْفَ عَلَيَّ أَمْرُهُمْ وَلَكِنِّي خَشِيتُ أَنْ تُكْتَبَ عَلَيْهِمْ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏يَعْنِي صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً فِي الْمَسْجِدِ فِي شَهْرِ رَمَضَانَ ‏","","",""],[24765,24765,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ خَادِمًا لَهُ قَطُّ وَلَا امْرَأَةً وَلَا ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ شَيْئًا قَطُّ إِلَّا أَنْ يُجَاهِدَ فِي سَبِيلِ اللَّهِ وَلَا خُيِّرَ بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا كَانَ أَحَبَّهُمَا إِلَيْهِ أَيْسَرُهُمَا حَتَّى يَكُونَ إِثْمًا فَإِذَا كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْ الْإِثْمِ وَلَا انْتَقَمَ لِنَفْسِهِ مِنْ شَيْءٍ يُؤْتَى إِلَيْهِ حَتَّى ‏ ‏تُنْتَهَكَ ‏ ‏حُرُمَاتُ اللَّهِ عَزَّ وَجَلَّ فَيَكُونَ هُوَ يَنْتَقِمُ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[24766,24766,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَوْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى النِّسَاءَ الْيَوْمَ ‏ ‏نَهَاهُنَّ عَنْ الْخُرُوجِ ‏ ‏أَوْ حَرَّمَ عَلَيْهِنَّ الْخُرُوجَ ‏","","",""],[24767,24767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏أَبَا جَهْمِ بْنِ حُذَيْفَةَ ‏ ‏مُصَدِّقًا ‏ ‏فَلَاحَهُ رَجُلٌ فِي صَدَقَتِهِ فَضَرَبَهُ ‏ ‏أَبُو جَهْمٍ ‏ ‏فَشَجَّهُ ‏ ‏فَأَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا ‏ ‏الْقَوَدَ ‏ ‏يَا رَسُولَ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكُمْ كَذَا وَكَذَا فَلَمْ يَرْضَوْا قَالَ فَلَكُمْ كَذَا وَكَذَا فَلَمْ يَرْضَوْا قَالَ فَلَكُمْ كَذَا وَكَذَا فَرَضُوا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي خَاطِبٌ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ قَالُوا نَعَمْ فَخَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ‏ ‏هَؤُلَاءِ ‏ ‏اللَّيْثِيِّينَ ‏ ‏أَتَوْنِي يُرِيدُونَ ‏ ‏الْقَوَدَ ‏ ‏فَعَرَضْتُ عَلَيْهِمْ كَذَا وَكَذَا فَرَضُوا رَضِيتُمْ قَالُوا لَا فَهَمَّ ‏ ‏الْمُهَاجِرُونَ ‏ ‏بِهِمْ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَكُفُّوا فَكَفُّوا ثُمَّ دَعَاهُمْ فَزَادَهُمْ وَقَالَ أَرَضِيتُمْ قَالُوا نَعَمْ قَالَ فَإِنِّي خَاطِبٌ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ قَالُوا نَعَمْ فَخَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ أَرَضِيتُمْ قَالُوا نَعَمْ ‏","","",""],[24768,24768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فَذَكَرَ حَدِيثًا ثُمَّ قَالَ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ الرُّؤْيَا الصَّادِقَةُ فِي النَّوْمِ وَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ ‏ ‏فَلَقِ الصُّبْحِ ‏ ‏ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ فَكَانَ يَأْتِي ‏ ‏حِرَاءَ ‏ ‏فَيَتَحَنَّثُ ‏ ‏فِيهِ ‏ ‏وَهُوَ التَّعَبُّدُ ‏ ‏اللَّيَالِيَ ذَوَاتِ الْعَدَدِ ‏ ‏وَيَتَزَوَّدُ ‏ ‏لِذَلِكَ ثُمَّ يَرْجِعُ إِلَى ‏ ‏خَدِيجَةَ ‏ ‏فَتُزَوِّدُهُ لِمِثْلِهَا حَتَّى فَجِئَهُ الْحَقُّ وَهُوَ فِي ‏ ‏غَارِ حِرَاءَ ‏ ‏فَجَاءَهُ الْمَلَكُ فِيهِ فَقَالَ اقْرَأْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنَا بِقَارِئٍ قَالَ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏حَتَّى بَلَغَ مِنِّي الْجَهْدُ ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ فَقُلْتُ مَا أَنَا بِقَارِئٍ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدُ ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ فَقُلْتُ مَا أَنَا بِقَارِئٍ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏الثَّالِثَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدُ ثُمَّ أَرْسَلَنِي فَقَالَ ‏ { ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ‏ ‏حَتَّى بَلَغَ ‏ ‏مَا لَمْ يَعْلَمْ ‏} ‏قَالَ فَرَجَعَ بِهَا تَرْجُفُ ‏ ‏بَوَادِرُهُ ‏ ‏حَتَّى دَخَلَ عَلَى ‏ ‏خَدِيجَةَ ‏ ‏فَقَالَ ‏ ‏زَمِّلُونِي ‏ ‏زَمِّلُونِي ‏ ‏فَزَمَّلُوهُ ‏ ‏حَتَّى ذَهَبَ عَنْهُ ‏ ‏الرَّوْعُ ‏ ‏فَقَالَ يَا ‏ ‏خَدِيجَةُ ‏ ‏مَالِي فَأَخْبَرَهَا الْخَبَرَ قَالَ وَقَدْ خَشِيتُ عَلَيَّ فَقَالَتْ لَهُ كَلَّا أَبْشِرْ فَوَاللَّهِ لَا يُخْزِيكَ اللَّهُ أَبَدًا إِنَّكَ لَتَصِلُ الرَّحِمَ وَتَصْدُقُ الْحَدِيثَ وَتَحْمِلُ ‏ ‏الْكَلَّ ‏ ‏وَتَقْرِي ‏ ‏الضَّيْفَ وَتُعِينُ عَلَى ‏ ‏نَوَائِبِ ‏ ‏الْحَقِّ ثُمَّ انْطَلَقَتْ بِهِ ‏ ‏خَدِيجَةُ ‏ ‏حَتَّى أَتَتْ بِهِ ‏ ‏وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى بْنِ قُصَيٍّ ‏ ‏وَهُوَ ابْنُ عَمِّ ‏ ‏خَدِيجَةَ ‏ ‏أَخِي أَبِيهَا وَكَانَ امْرَأً ‏ ‏تَنَصَّرَ ‏ ‏فِي الْجَاهِلِيَّةِ وَكَانَ يَكْتُبُ الْكِتَابَ الْعَرَبِيَّ فَكَتَبَ بِالْعَرَبِيَّةِ مِنْ الْإِنْجِيلِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ فَقَالَتْ ‏ ‏خَدِيجَةُ ‏ ‏أَيْ ابْنَ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ فَقَالَ ‏ ‏وَرَقَةُ ‏ ‏ابْنَ أَخِي مَا ‏ ‏تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَى فَقَالَ ‏ ‏وَرَقَةُ ‏ ‏هَذَا ‏ ‏النَّامُوسُ ‏ ‏الَّذِي أُنْزِلَ عَلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَا لَيْتَنِي فِيهَا ‏ ‏جَذَعًا ‏ ‏أَكُونَ حَيًّا حِينَ يُخْرِجُكَ قَوْمُكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَ مُخْرِجِيَّ هُمْ فَقَالَ ‏ ‏وَرَقَةُ ‏ ‏نَعَمْ لَمْ يَأْتِ رَجُلٌ قَطُّ بِمَا جِئْتَ بِهِ إِلَّا عُودِيَ وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا ‏ ‏مُؤَزَّرًا ‏ ‏ثُمَّ لَمْ ‏ ‏يَنْشَبْ ‏ ‏وَرَقَةُ ‏ ‏أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ ‏ ‏فَتْرَةً ‏ ‏حَتَّى حَزِنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا بَلَغَنَا حُزْنًا ‏ ‏غَدَا ‏ ‏مِنْهُ مِرَارًا كَيْ ‏ ‏يَتَرَدَّى ‏ ‏مِنْ رُءُوسِ شَوَاهِقِ الْجِبَالِ فَكُلَّمَا ‏ ‏أَوْفَى ‏ ‏بِذِرْوَةِ جَبَلٍ لِكَيْ يُلْقِيَ نَفْسَهُ مِنْهُ تَبَدَّى لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ لَهُ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّكَ رَسُولُ اللَّهِ حَقًّا فَيُسْكِنُ ذَلِكَ ‏ ‏جَأْشَهُ ‏ ‏وَتَقَرُّ نَفْسُهُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏فَيَرْجِعُ فَإِذَا طَالَتْ عَلَيْهِ وَفَتَرَ الْوَحْيُ ‏ ‏غَدَا ‏ ‏لِمِثْلِ ذَلِكَ فَإِذَا ‏ ‏أَوْفَى ‏ ‏بِذِرْوَةِ جَبَلٍ تَبَدَّى لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ لَهُ مِثْلَ ذَلِكَ ‏","","",""],[24769,24769,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏الْحَبَشَةَ ‏ ‏لَعِبُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَانِي فَنَظَرْتُ مِنْ فَوْقِ ‏ ‏مَنْكِبِهِ ‏ ‏حَتَّى شَبِعْتُ ‏","","",""],[24770,24770,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ تَلْعَبُ بِالْبَنَاتِ فَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي بِصَوَاحِبِي يَلْعَبْنَ مَعِي ‏","","",""],[24771,24771,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏عُرْوَةُ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ ‏ ‏لِتَعْلَمَ ‏ ‏يَهُودُ ‏ ‏أَنَّ فِي دِينِنَا فُسْحَةً إِنِّي أُرْسِلْتُ ‏ ‏بِحَنِيفِيَّةٍ ‏ ‏سَمْحَةٍ ‏","","",""],[24772,24772,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا وَكَانَ أَحَبُّ الصَّلَاةِ إِلَيْهِ مَا دَاوَمَ عَلَيْهَا وَإِنْ قَلَّتْ وَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا ‏ ‏يَمَلُّ ‏ ‏حَتَّى ‏ ‏تَمَلُّوا ‏","","",""],[24773,24773,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏أَكْثَرُ صَوْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ شَهْرٍ مِنْ السَّنَةِ مِنْ شَعْبَانَ فَإِنَّهُ كَانَ يَصُومُهُ كُلَّهُ ‏","","",""],[24774,24774,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَتْ لَيْلَةُ ‏ ‏النَّفْرِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏يَرْجِعُونَ بِعُمْرَةٍ وَحَجَّةٍ وَأَرْجِعُ بِحَجَّةٍ فَبَعَثَ مَعِي أَخِي فَاعْتَمَرْتُ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُصْعِدًا ‏ ‏مُدْلِجًا ‏ ‏عَلَى أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَنَا ‏ ‏مُدْلِجَةٌ ‏ ‏عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏","","",""],[24775,24775,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏مِصْدَعِ بْنِ يَحْيَى الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ وَيَمُصُّ لِسَانَهَا ‏","","",""],[24776,24776,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فُرِضَتْ الصَّلَاةُ رَكْعَتَيْنِ فَزَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاةِ الْحَضَرِ وَتَرَكَ صَلَاةَ السَّفَرِ عَلَى نَحْوِهَا ‏","","",""],[24777,24777,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَلْعَبُ بِالْبَنَاتِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ يَأْتِي بِصَوَاحِبِي فَكُنَّ إِذَا رَأَيْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْقَمِعْنَ ‏ ‏مِنْهُ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَرِّبُهُنَّ إِلَيَّ يَلْعَبْنَ مَعِي ‏","","",""],[24778,24778,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمِ بْنِ يَنَّاقٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏زَوَّجَتْ ابْنَةً لَهَا فَاشْتَكَتْ وَتَسَاقَطَ شَعَرُهَا فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّ زَوْجَهَا يُرِيدُهَا فَأَصِلُ شَعْرَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْمُوصِلَاتِ ‏","","",""],[24779,24779,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ أَبِي وَهْبٍ النَّصْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ بْنِ كُرَيْزٍ الْخُزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَوَضَّأَ ‏ ‏خَلَّلَ ‏ ‏لِحْيَتَهُ بِالْمَاءِ ‏","","",""],[24780,24780,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ أَبِي وَهْبٍ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ ثَرْوَانَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ بْنِ كُرَيْزٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ ‏ ‏خَلَّلَ ‏ ‏لِحْيَتَهُ بِالْمَاءِ ‏","","",""],[24781,24781,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى السَّامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بُرْدٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَفْتَحْتُ الْبَابَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي فَمَشَى فِي الْقِبْلَةِ ‏ ‏إِمَّا عَنْ يَمِينِهِ وَإِمَّا عَنْ يَسَارِهِ ‏ ‏حَتَّى فَتَحَ لِي ثُمَّ رَجَعَ إِلَى مُصَلَّاهُ ‏","","",""],[24782,24782,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ ‏ ‏تُرَجِّلُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ حَائِضٌ وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏فِي الْمَسْجِدِ فَيُنَاوِلُهَا رَأْسَهُ وَهِيَ فِي حُجْرَتِهَا ‏","","",""],[24783,24783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ بِنَحْوِ ‏ ‏الْمُدِّ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏بِقَدْرِ ‏ ‏الْمُدِّ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏أَوْ ‏ ‏مُعَاذَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏وَقَالَ ‏ ‏بِقَدْرِ ‏ ‏الْمُدِّ ‏ ‏وَبِقَدْرِ ‏ ‏الصَّاعِ ‏","","",""],[24784,24784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ بِقَدْرِ ‏ ‏الْمُدِّ ‏ ‏أَوْ نَحْوِهِ ‏","","",""],[24785,24785,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ ‏ ‏تَدَّانُ ‏ ‏فَقِيلَ لَهَا مَا يَحْمِلُكِ عَلَى الدَّيْنِ وَلَكِ عَنْهُ ‏ ‏مَنْدُوحَةٌ ‏ ‏قَالَتْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ ‏ ‏يُدَانُ ‏ ‏وَفِي نَفْسِهِ أَدَاؤُهُ إِلَّا كَانَ مَعَهُ مِنْ اللَّهِ عَوْنٌ فَأَنَا أَلْتَمِسُ ذَلِكَ الْعَوْنَ ‏","","",""],[24786,24786,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏شُمَيْسَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏","","",""],[24787,24787,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْلِسُ بَعْدَ صَلَاتِهِ إِلَّا قَدْرَ مَا يَقُولُ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[24788,24788,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ ‏ ‏يُبَاشِرَ ‏ ‏إِحْدَانَا وَهِيَ حَائِضٌ أَمَرَهَا ‏ ‏فَاتَّزَرَتْ ‏ ‏فَإِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[24789,24789,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ بِنْتِ عَبْدِ اللَّهِ ‏ ‏قَالَتْ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَغْتَسِلُ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24790,24790,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَوْ رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَحْدَثَ النِّسَاءُ لَمَنَعَهُنَّ الْمَسْجِدَ كَمَا مُنِعَتْ نِسَاءُ ‏ ‏بَنِي إِسْرَائِيلَ ‏","","",""],[24791,24791,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ أَخِي عَمْرَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَ الْفَجْرِ فَيُخَفِّفُهُمَا حَتَّى إِنْ كُنْتُ لَأَقُولُ هَلْ قَرَأَ فِيهِمَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏","","",""],[24792,24792,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَكِفًا وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةِ الْإِنْسَانِ قَالَتْ فَغَسَلْتُ رَأْسَهُ وَإِنَّ بَيْنِي وَبَيْنَهُ لَعَتَبَةُ الْبَابِ ‏","","",""],[24793,24793,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَصَابَ ثَوْبَهُ الْمَنِيُّ ‏ ‏غَسَلَ مَا أَصَابَ مِنْ ثَوْبِهِ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ وَأَنَا أَنْظُرُ إِلَى بُقْعَةٍ فِي ثَوْبِهِ ذَلِكَ مِنْ أَثَرِ الْغُسْلِ ‏","","",""],[24794,24794,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ لِي مَنْ أَنْتَ فَقُلْتُ ‏ ‏سَعْدُ بْنُ هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَتْ رَحِمَ اللَّهُ أَبَاكَ قَالَ قُلْتُ أَخْبِرِينِي عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فَقُلْتُ أَجَلْ وَلَكِنْ أَخْبِرِينِي قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ عِشَاءَ الْآخِرَةِ ثُمَّ يَأْوِي إِلَى فِرَاشِهِ فَإِذَا كَانَ مِنْ جَوْفِ اللَّيْلِ قَامَ إِلَى طَهُورِهِ فَتَوَضَّأَ ثُمَّ دَخَلَ الْمَسْجِدَ فَصَلَّى ‏ ‏ثَمَانِيَ رَكَعَاتٍ يُسَوِّي بَيْنَ الْقِرَاءَةِ فِيهِنَّ وَالرُّكُوعِ وَالسُّجُودِ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏بِرَكْعَةٍ ثُمَّ ‏ ‏يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ ثُمَّ يَضَعُ رَأْسَهُ فَرُبَّمَا جَاءَ ‏ ‏بِلَالٌ ‏ ‏فَآذَنَهُ بِالصَّلَاةِ قَبْلَ أَنْ ‏ ‏يُغْفِيَ ‏ ‏وَرُبَّمَا شَكَكْتُ ‏ ‏أَغْفَى ‏ ‏أَوْ لَمْ ‏ ‏يُغْفِ ‏ ‏حَتَّى يُؤْذِنَهُ بِالصَّلَاةِ قَالَتْ فَكَانَتْ تِلْكَ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَسَنَّ ‏ ‏وَلَحُمَ ‏ ‏وَكَانَ ‏ ‏يُصَلِّي بِالنَّاسِ الْعِشَاءَ الْآخِرَةَ ثُمَّ ‏ ‏يَأْوِي إِلَى فِرَاشِهِ فَإِذَا كَانَ فِي جَوْفِ اللَّيْلِ قَامَ إِلَى طَهُورِهِ فَتَوَضَّأَ ثُمَّ دَخَلَ الْمَسْجِدَ فَصَلَّى سِتَّ رَكَعَاتٍ يُسَوِّي بَيْنَهُنَّ فِي الرُّكُوعِ وَالسُّجُودِ وَالْقِرَاءَةِ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏بِرَكْعَةٍ ثُمَّ ‏ ‏يُصَلِّي ‏ ‏رَكْعَتَيْنِ وَهُوَ جَالِسٌ فَرُبَّمَا لَمْ ‏ ‏يُغْفِ ‏ ‏حَتَّى يَجِيءَ ‏ ‏بِلَالٌ ‏ ‏فَيُؤْذِنَهُ بِالصَّلَاةِ ‏ ‏وَرُبَّمَا شَكَكْتُ ‏ ‏أَغْفَى ‏ ‏أَوْ لَمْ ‏ ‏يُغْفِ ‏","","",""],[24795,24795,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَهْزُ بْنُ حَكِيمٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يَقُولُ ‏ ‏سُئِلَتْ ‏ ‏عَائِشَةُ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَتْ كَانَ ‏ ‏يُصَلِّي الْعِشَاءَ ثُمَّ ‏ ‏يُصَلِّي بَعْدَهَا رَكْعَتَيْنِ ثُمَّ يَنَامُ فَإِذَا اسْتَيْقَظَ وَعِنْدَهُ وَضُوءُهُ مُغَطًّى وَسِوَاكُهُ اسْتَاكَ ثُمَّ تَوَضَّأَ فَقَامَ فَصَلَّى ثَمَانِ رَكَعَاتٍ يَقْرَأُ فِيهِنَّ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَمَا شَاءَ مِنْ الْقُرْآنِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً مَا شَاءَ اللَّهُ مِنْ الْقُرْآنِ ‏ ‏فَلَا يَقْعُدُ فِي شَيْءٍ مِنْهُنَّ إِلَّا فِي الثَّامِنَةِ فَإِنَّهُ يَقْعُدُ فِيهَا فَيَتَشَهَّدُ ثُمَّ يَقُومُ وَلَا يُسَلِّمُ فَيُصَلِّيَ رَكْعَةً وَاحِدَةً ثُمَّ يَجْلِسُ فَيَتَشَهَّدُ وَيَدْعُو ثُمَّ يُسَلِّمُ تَسْلِيمَةً وَاحِدَةً السَّلَامُ عَلَيْكُمْ يَرْفَعُ بِهَا صَوْتَهُ حَتَّى يُوقِظَنَا ثُمَّ يُكَبِّرُ وَهُوَ جَالِسٌ فَيَقْرَأُ ثُمَّ يَرْكَعُ وَيَسْجُدُ وَهُوَ جَالِسٌ فَيُصَلِّي جَالِسًا رَكْعَتَيْنِ فَهَذِهِ إِحْدَى عَشْرَةَ رَكْعَةً فَلَمَّا كَثُرَ لَحْمُهُ وَثَقُلَ جَعَلَ التِّسْعَ سَبْعًا لَا يَقْعُدُ إِلَّا كَمَا يَقْعُدُ فِي الْأُولَى وَيُصَلِّي الرَّكْعَتَيْنِ قَاعِدًا فَكَانَتْ هَذِهِ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قَبَضَهُ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏بَهْزِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ لِأُمِّ الْمُؤْمِنِينَ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ قَالَتْ كَانَ ‏ ‏يُصَلِّي الْعِشَاءَ فَذَكَرَ الْحَدِيثَ وَيُصَلِّي رَكْعَتَيْنِ قَائِمًا يَرْفَعُ صَوْتَهُ كَأَنَّهُ يُوقِظُنَا بَلْ يُوقِظُنَا ثُمَّ يَدْعُو بِدُعَاءٍ يُسْمِعُنَا ثُمَّ يُسَلِّمُ تَسْلِيمَةً ثُمَّ يَرْفَعُ بِهَا صَوْتَهُ ‏","","",""],[24796,24796,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ وَالْمَوْتُ قَبْلَ لِقَاءِ اللَّهِ ‏","","",""],[24797,24797,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عَبْدِ اللَّهِ الْجَدَلِيُّ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏كَيْفَ كَانَ خُلُقُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَهْلِهِ قَالَتْ كَانَ أَحْسَنَ النَّاسِ خُلُقًا لَمْ يَكُنْ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا ‏ ‏سَخَّابًا ‏ ‏بِالْأَسْوَاقِ وَلَا يُجْزِئُ بِالسَّيِّئَةِ مِثْلَهَا وَلَكِنْ يَعْفُو وَيَصْفَحُ ‏","","",""],[24798,24798,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يُحْرِمَ ادَّهَنَ بِأَطْيَبِ دُهْنٍ يَجِدُهُ حَتَّى إِنِّي لَأَرَى بَصِيصَ الدُّهْنِ فِي شَعَرِهِ وَلَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏الْهَدْيِ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَبْعَثُ بِهِ فَمَا يَعْتَزِلُ مِنَّا امْرَأَةً ‏","","",""],[24799,24799,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَاعِدًا قَالَتْ كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ طَوِيلًا قَاعِدًا وَيُصَلِّي مِنْ اللَّيْلِ طَوِيلًا قَائِمًا فَإِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا ‏","","",""],[24800,24800,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مُتَّكِئًا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ يَا ‏ ‏أَبَا عَائِشَةَ ‏ ‏أَنَا أَوَّلُ مَنْ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ هَذِهِ قَالَ ‏ ‏ذَلِكَ ‏ ‏جِبْرِيلُ ‏ ‏لَمْ أَرَهُ فِي صُورَتِهِ الَّتِي خُلِقَ فِيهَا إِلَّا مَرَّتَيْنِ رَأَيْتُهُ مُنْهَبِطًا مِنْ السَّمَاءِ سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""]];
